
def _es_bloqueo_waf_403(texto: str) -> bool:
    if not texto:
        return True
    t = texto.upper()
    patrones_bloqueo = [
        "403 ERROR",
        "THE REQUEST COULD NOT BE SATISFIED",
        "GENERATED BY CLOUDFRONT",
        "REQUEST BLOCKED",
        "ACCESS DENIED",
        "ERROR 1020",
        "CLOUDFLARE"
    ]
    return any(p in t for p in patrones_bloqueo)

