def _normalizar_para_regex(texto):
    """
    Normaliza el texto eliminando acentos para una comparación con expresiones
    regulares robusta, uniforme e insensible a mayúsculas/minúsculas y tildes.
    """
    if not texto:
        return ""
    reemplazos = {
        'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u',
        'Á': 'a', 'É': 'e', 'Í': 'i', 'Ó': 'o', 'Ú': 'u',
        'ü': 'u', 'Ü': 'u', 'ñ': 'n', 'Ñ': 'n'
    }
    t = str(texto).lower()
    for o, d in reemplazos.items():
        t = t.replace(o, d)
    return t



# ==============================================================================
# LLAMADA ÚNICA A GEMINI (JSON validado, modelo vigente, reintentos con backoff)
# ==============================================================================
_ULTIMA_LLAMADA_IA = [0.0]
_FALLOS_CUOTA = [0]


def _generar_json_openai(prompt, temperatura=0.2, max_tokens=8192, timeout=None, intentos=3,
                         base_url=None, api_key=None, modelo=None):
    """Llamada a un proveedor compatible con OpenAI (DeepSeek, Groq, OpenRouter...).

    Devuelve (dict, "") o (None, motivo). Misma lógica de reintentos que Gemini.
    """
    _clave = api_key or IA_API_KEY
    if not _clave:
        return None, "IA_API_KEY no configurada"
    url = (base_url or IA_BASE_URL).rstrip("/") + "/chat/completions"
    payload = {
        "model": modelo or IA_MODELO,
        "messages": [
            {"role": "system",
             "content": "Eres un consultor experto en contratacion publica chilena. "
                        "Respondes SIEMPRE con JSON valido, sin markdown."},
            {"role": "user", "content": prompt},
        ],
        "temperature": temperatura,
        "max_tokens": max_tokens,
        "response_format": {"type": "json_object"},
    }
    cabeceras = {
        "Authorization": f"Bearer {_clave}",
        "Content-Type": "application/json",
    }
    ultimo = "sin intentos"
    for n in range(1, max(1, intentos) + 1):
        _faltante = PAUSA_MINIMA_IA - (time.time() - _ULTIMA_LLAMADA_IA[0])
        if _faltante > 0:
            time.sleep(_faltante)
        _ULTIMA_LLAMADA_IA[0] = time.time()
        try:
            r = requests.post(url, json=payload, headers=cabeceras,
                              timeout=timeout or GEMINI_TIMEOUT)
            _error_400 = (r.text or "").lower()
            if r.status_code == 413 or "too large" in _error_400 or "tokens per minute" in _error_400:
                ultimo = f"HTTP 413: cupo de tokens por minuto agotado en {IA_MODELO}"
                if n < intentos:
                    _espera_tpm = min(30 * n, 90)
                    print(f"      [!] Cupo de tokens por minuto agotado; "
                          f"esperando {_espera_tpm}s para reintentar (sin recortar)")
                    time.sleep(_espera_tpm)
                    continue
                for _msg in payload.get("messages", []):
                    if _msg.get("role") == "user":
                        _largo = len(_msg.get("content") or "")
                        _msg["content"] = _msg["content"][:max(2000, int(_largo * 0.35))]
                print("      [!] Se reintenta con menos texto")
                continue
            if r.status_code == 400 and ("response_format" in _error_400
                                            or "json_validate" in _error_400
                                            or "validate json" in _error_400):
                print("      [!] El proveedor rechazo el JSON estricto; se reintenta en modo texto")
                payload.pop("response_format", None)
                continue
            if r.status_code != 200:
                detalle = (r.text or "")[:220].replace("\n", " ")
                ultimo = f"HTTP {r.status_code} ({IA_MODELO}): {detalle}"
                if r.status_code == 429:
                    _FALLOS_CUOTA[0] += 1
                    espera = min(35 * n, 120)
                elif r.status_code in (500, 502, 503, 504):
                    espera = min(25 * n, 70)
                else:
                    espera = 0
                if espera and n < intentos:
                    print(f"      [!] {IA_MODELO} saturado (HTTP {r.status_code}); "
                          f"reintentando en {espera}s...")
                    time.sleep(espera)
                    continue
            else:
                _FALLOS_CUOTA[0] = 0
                datos = r.json()
                contenido = ((datos.get("choices") or [{}])[0].get("message") or {}).get("content") or ""
                contenido = contenido.strip()
                if not contenido:
                    ultimo = "respuesta vacía del proveedor"
                else:
                    contenido = re.sub(r"^\s*```(?:json)?|```\s*$", "", contenido,
                                       flags=re.IGNORECASE).strip()
                    try:
                        return json.loads(contenido), ""
                    except Exception as e_json:
                        i = contenido.find("{")
                        j = contenido.rfind("}")
                        if i >= 0 and j > i:
                            try:
                                return json.loads(contenido[i:j + 1]), ""
                            except Exception:
                                pass
                        ultimo = f"JSON inválido ({e_json}) largo={len(contenido)}"
        except Exception as e_red:
            ultimo = f"excepción de red: {e_red}"
        if n < intentos:
            time.sleep(min(3 * n, 15))
    return None, ultimo


def _ia_limite_alcanzado():
    """True si Gemini ya rechazó varias veces por cuota en esta corrida."""
    return _FALLOS_CUOTA[0] >= MAX_FALLOS_CUOTA


IA_PREMIUM_URL = os.getenv("IA_PREMIUM_URL", "").strip().rstrip("/")
IA_PREMIUM_KEY = os.getenv("IA_PREMIUM_KEY", "").strip()
IA_PREMIUM_MODELO = os.getenv("IA_PREMIUM_MODELO", "").strip()
IA_PREMIUM_TOPE_TEXTO = int(os.getenv("IA_PREMIUM_TOPE_TEXTO", "60000"))
PREMIUM_ACTIVO = bool(IA_PREMIUM_URL and IA_PREMIUM_KEY and IA_PREMIUM_MODELO)


def _gemini_generar_json(prompt, temperatura=0.2, max_tokens=8192, timeout=None, intentos=3, premium=False):
    """Devuelve (dict, "") si todo va bien, o (None, motivo_del_fallo).

    Por qué existe: con el modelo 1.5-flash (retirado) o con la respuesta truncada,
    json.loads fallaba y TODOS los agentes caían en silencio al texto genérico.
    Aquí el fallo se informa y se reintenta.
    """
    if premium and PREMIUM_ACTIVO:
        return _generar_json_openai(prompt, temperatura, max_tokens, timeout, intentos,
                                    base_url=IA_PREMIUM_URL, api_key=IA_PREMIUM_KEY,
                                    modelo=IA_PREMIUM_MODELO)
    if PROVEEDOR_IA == "openai":
        return _generar_json_openai(prompt, temperatura, max_tokens, timeout, intentos)
    if not API_KEY_GEMINI:
        return None, "GEMINI_API_KEY no configurada en el entorno"
    modelos = [MODELO_GEMINI]
    for _alt in ("gemini-3.8-flash", "gemini-2.5-flash", "gemini-2.0-flash"):
        if _alt not in modelos:
            modelos.append(_alt)
    indice_modelo = 0
    url = ""
    payload = {
        "contents": [{"parts": [{"text": prompt}]}],
        "generationConfig": {
            "temperature": temperatura,
            "maxOutputTokens": max_tokens,
            "responseMimeType": "application/json",
        },
    }
    ultimo = "sin intentos"
    for n in range(1, max(1, intentos) + 1):
        # Ritmo mínimo entre llamadas
        _faltante = PAUSA_MINIMA_IA - (time.time() - _ULTIMA_LLAMADA_IA[0])
        if _faltante > 0:
            time.sleep(_faltante)
        _ULTIMA_LLAMADA_IA[0] = time.time()
        modelo_actual = modelos[min(indice_modelo, len(modelos) - 1)]
        url = ("https://generativelanguage.googleapis.com/v1beta/models/"
               f"{modelo_actual}:generateContent?key={API_KEY_GEMINI}")
        try:
            r = requests.post(url, json=payload, timeout=timeout or GEMINI_TIMEOUT)
            if r.status_code != 200:
                detalle = (r.text or "")[:220].replace("\n", " ")
                ultimo = f"HTTP {r.status_code}: {detalle}"
                if r.status_code in (400, 404):
                    ultimo += "  <-- modelo inexistente o prompt inválido (revisa GEMINI_MODEL)"
                    if indice_modelo < len(modelos) - 1:
                        indice_modelo += 1
                        print(f"      [!] El modelo {modelo_actual} no está disponible; "
                              f"se prueba con {modelos[indice_modelo]}")
                        continue
                if r.status_code in (429, 500, 502, 503, 504):
                    # Saturación temporal de Google: se espera y se reintenta
                    if r.status_code == 429:
                        _FALLOS_CUOTA[0] += 1
                    espera = min(35 * n, 120) if r.status_code == 429 else min(25 * n, 70)
                    print(f"      [!] Gemini saturado (HTTP {r.status_code}); "
                          f"reintentando en {espera}s...")
                    time.sleep(espera)
            else:
                js = r.json()
                cand = (js.get("candidates") or [{}])[0]
                fin = cand.get("finishReason", "")
                partes = (cand.get("content") or {}).get("parts") or []
                txt = "".join(p.get("text", "") for p in partes).strip()
                if not txt:
                    ultimo = f"respuesta vacía (finishReason={fin})"
                else:
                    txt = re.sub(r"^\s*```(?:json)?|```\s*$", "", txt, flags=re.IGNORECASE).strip()
                    _FALLOS_CUOTA[0] = 0
                    try:
                        return json.loads(txt), ""
                    except Exception as e:
                        i, j = txt.find("{"), txt.rfind("}")
                        if i >= 0 and j > i:
                            try:
                                return json.loads(txt[i:j + 1]), ""
                            except Exception:
                                pass
                        ultimo = (f"JSON inválido ({e}) finishReason={fin} "
                                  f"largo={len(txt)} (si es MAX_TOKENS, sube max_tokens)")
        except Exception as e:
            ultimo = f"excepción de red: {e}"
        if n < intentos:
            time.sleep(min(3 * n, 15))
    return None, ultimo


# ==============================================================================
# HORARIO DE ESCANEO (hora de Chile, sin depender de la zona del servidor)
# ==============================================================================
def _ahora_chile():
    """Hora actual en Chile. Si falta la base de zonas, usa la hora local."""
    try:
        from zoneinfo import ZoneInfo
        return datetime.datetime.now(ZoneInfo("America/Santiago"))
    except Exception:
        return datetime.datetime.now()


def _marca_hora(ahora=None):
    """Identificador de la hora actual, para no correr dos veces la misma."""
    ahora = ahora or _ahora_chile()
    return f"{ahora:%Y-%m-%d}-{ahora.hour:02d}"


def _estado_planificador(guardar=None):
    ruta = os.path.join(DIRECTORIO_RAIZ, "planificador_estado.json")
    datos = {}
    try:
        if os.path.isfile(ruta):
            with open(ruta, encoding="utf-8") as f:
                datos = json.load(f) or {}
    except Exception:
        datos = {}
    if guardar is not None:
        try:
            with open(ruta, "w", encoding="utf-8") as f:
                json.dump(guardar, f, ensure_ascii=False, indent=2)
        except Exception:
            pass
    return datos


def _ya_corrio_esta_hora():
    return _estado_planificador().get("ultima_marca") == _marca_hora()


def _marcar_corrida():
    estado = _estado_planificador()
    estado["ultima_marca"] = _marca_hora()
    estado["ultima_ejecucion"] = _ahora_chile().strftime("%Y-%m-%d %H:%M")
    _estado_planificador(estado)


def _hora_de_escanear(ahora=None):
    ahora = ahora or _ahora_chile()
    return ahora.hour in HORARIO_ESCANEO


def _es_hora_barrido_final(ahora=None):
    ahora = ahora or _ahora_chile()
    return bool(HORARIO_ESCANEO) and ahora.hour >= max(HORARIO_ESCANEO)


def describir_horario():
    if not HORARIO_ESCANEO:
        return "sin horario definido (corre en cualquier momento)"
    horas = ", ".join(f"{h:02d}:00" for h in HORARIO_ESCANEO)
    return (f"{horas} · el de las {max(HORARIO_ESCANEO):02d}:00 es el BARRIDO FINAL "
            f"(revisa hoy y ayer, con más cupo)")


def mostrar_horario():
    ahora = _ahora_chile()
    print("")
    print("🕒 HORARIO DE ESCANEO (hora de Chile)")
    print(f"   {describir_horario()}")
    print(f"   Ahora son las {ahora:%H:%M} del {ahora:%d-%m-%Y}")
    if HORARIO_ESCANEO:
        proxima = next((h for h in HORARIO_ESCANEO if h > ahora.hour), None)
        if proxima is None:
            proxima = HORARIO_ESCANEO[0]
            cuando = "mañana"
        else:
            cuando = "hoy"
        print(f"   Próxima corrida automática: {proxima:02d}:00 ({cuando})")
    if _hora_de_escanear(ahora):
        print("   ✔ Ahora SÍ corresponde escanear")
    else:
        print("   ⏸ Ahora NO corresponde (con --auto se saltaría; a mano corre igual)")
    print("")


