# GET CON REINTENTOS (la API de Compra Ágil a veces tarda más de 20s)
# ==============================================================================
def _crear_sesion_api():
    """Sesión con huella TLS de navegador si curl_cffi está disponible."""
    if CURL_CFFI_DISPONIBLE:
        try:
            sesion = curl_requests.Session(impersonate="chrome")
            sesion.headers.update(HEADERS_WEB)
            return sesion
        except Exception:
            pass
    sesion = requests.Session()
    sesion.headers.update(HEADERS_WEB)
    return sesion


def _get_con_reintento(url, headers=None, timeout=45, intentos=2, sesion=None):
    """GET tolerante a timeouts. Devuelve la respuesta o None."""
    cliente = sesion or requests
    ultimo = None
    for numero in range(1, max(1, intentos) + 1):
        try:
            respuesta = cliente.get(url, headers=headers or {}, timeout=timeout)
            if getattr(respuesta, "status_code", 0) == 429 and numero < intentos:
                print("      [!] La API pidió esperar (HTTP 429). Reintentando en 12s...")
                time.sleep(12)
                continue
            return respuesta
        except Exception as e:
            ultimo = e
            if numero < intentos:
                time.sleep(2 * numero)
    print(f"      [!] Sin respuesta de la API tras {intentos} intento(s): {str(ultimo)[:110]}")
    return None

LEY_MULTAS = """MARCO LEGAL OBLIGATORIO PARA MULTAS Y DEFENSA DEL PROVEEDOR (cita siempre el artículo):
- DS 661/2024 (Reglamento de la Ley 19.886), Art. 135: las multas, el cobro de garantía y el término anticipado deben estar tipificados de forma clara e inequívoca en las Bases o en el contrato, y ser proporcionales al incumplimiento.
- Art. 136: las Bases y/o el contrato deben fijar un tope máximo de multas que NUNCA puede superar el 30% del precio total del contrato.
- Art. 137: prohibida la multa automática o de plano; exige notificación escrita, traslado y plazo prudente para descargos, y resolución fundada tramitada en Gestión de Contratos.
- Art. 138: el organismo NO puede cobrar multas si mantiene pagos o facturas impagas devengadas en meses anteriores a la exigibilidad de la multa.
- Art. 139: solo si las multas y garantías no cubren el daño real procede demanda de indemnización en sede judicial.
- Eximentes: caso fortuito o fuerza mayor (Art. 45 Código Civil) y causas no imputables al proveedor (atrasos de la propia entidad, caída de Mercado Público, falta de accesos o aprobaciones).
- Impugnación: Recurso de Reposición y, en subsidio, Jerárquico, plazo fatal de 5 días hábiles administrativos (Art. 59 Ley 19.880); plataforma de reclamos de ChileCompra con 5 días hábiles.
- Ley 21.634: el Tribunal de Contratación Pública también conoce ilegalidades de la etapa de ejecución contractual (multas, cobro de garantías, término anticipado).
- Registro de Proveedores: las multas ejecutoriadas afectan la calificación de comportamiento contractual (Arts. 154 y 157 DS 661).

REGLAS DE AUDITORÍA ANTI-MULTAS (evalúa cada una; reporta hallazgo, norma, riesgo y acción):
M-01 Existe tope de multas y es menor o igual al 30% del contrato (Art. 136). Si no existe o supera el 30%, es ALERTA DE ILEGALIDAD.
M-02 La multa se calcula sobre el monto neto, sobre el total con IVA o sobre el ítem atrasado (Art. 135, proporcionalidad). Si aplica porcentaje sobre el total por atraso de un hito menor, es RIESGO FINANCIERO ALTO.
M-03 Las causales son objetivas o quedan a juicio exclusivo del organismo (Art. 135, claridad). Si son subjetivas, sugerir pregunta al foro para objetivar el estándar.
M-04 Desde cuándo corre el plazo: orden de compra, aceptación de la OC o acta de inicio (Art. 135). En TI debe correr desde la entrega de accesos e insumos.
M-05 Hay notificación previa y plazo de descargos antes de cursar la multa (Art. 137). Si dice multa automática sin trámite, es infracción al debido proceso.
M-06 Se respetan Reposición y Jerárquico de 5 días hábiles (Art. 137 DS 661 y Art. 59 Ley 19.880). Verificar que no se renuncie anticipadamente a esos recursos.
M-07 Contempla eximente por atrasos imputables a la entidad o por fuerza mayor (Art. 135 y Art. 45 Código Civil). Recomendar dejar constancia escrita de cada demora de la contraparte.
M-08 Regula la prohibición de descontar multas cuando hay facturas impagas de meses anteriores (Art. 138). Recordar este escudo financiero en el dossier."""

def _motor_precios(presupuesto, costo_interno=None):
    """Motor de precios justificado (v9.3) · utilizable por Agente 3 y Agente 4.

    Recorre el rango 78%-99% del tope, estima la probabilidad de adjudicar
    según el precio de la competencia y elige el punto que maximiza
    margen x probabilidad, respetando el margen objetivo del cliente.
    """
    presupuesto = int(presupuesto or 0)
    if presupuesto <= 0:
        presupuesto = 1
    costo_ratio = max(0.30, min(0.92, float(os.getenv("COSTO_SOBRE_TOPE", "0.62"))))
    costo = int(costo_interno or round(presupuesto * costo_ratio))
    peso_precio = max(0.05, min(0.95, float(os.getenv("PESO_PRECIO", "0.40"))))
    margen_objetivo = max(0.0, min(0.90, float(os.getenv("MARGEN_OBJETIVO", "0.35"))))
    pct_competencia = max(0.50, min(0.99, float(os.getenv("PCT_COMPETENCIA", "0.85"))))
    competidores = max(1, int(os.getenv("COMPETIDORES_ESTIMADOS", "3")))

    def _probabilidad(pct):
        x = (pct_competencia - pct) / 0.035
        return 1.0 / (1.0 + 2.718281828459045 ** (-x))

    def evaluar(pct):
        bruto = int(round(presupuesto * pct))
        neto = int(round(bruto / 1.19))
        iva = bruto - neto
        margen = neto - costo
        margen_pct = (margen / neto * 100.0) if neto else 0.0
        puntaje_precio = (peso_precio * 100.0) * min(1.0, pct_competencia / pct)
        puntaje_tecnico = (1.0 - peso_precio) * 100.0
        prob = _probabilidad(pct)
        return {
            "porcentaje_tope": int(round(pct * 100)),
            "total_bruto_clp": bruto,
            "neto_clp": neto,
            "iva_19_clp": iva,
            "costo_interno_clp": costo,
            "margen_clp": margen,
            "margen_pct": round(margen_pct, 1),
            "puntaje_precio": round(puntaje_precio, 1),
            "puntaje_estimado": round(puntaje_precio + puntaje_tecnico, 1),
            "prob_adjudicacion_pct": round(prob * 100, 1),
            "utilidad_esperada_clp": int(round(margen * prob)),
        }

    candidatos = [evaluar(p / 100.0) for p in range(78, 100)]
    indice_eq = max(range(len(candidatos)), key=lambda i: candidatos[i]["utilidad_esperada_clp"])
    equilibrado = candidatos[indice_eq]

    piso_margen = max(3.0, margen_objetivo * 100.0 * 0.3)
    indice_ag = max(0, indice_eq - 3)
    if candidatos[indice_ag]["margen_pct"] < piso_margen:
        indice_ag = 0
    agresivo = candidatos[indice_ag]

    indice_co = min(len(candidatos) - 1, indice_eq + 2)
    if candidatos[indice_co]["prob_adjudicacion_pct"] < 20.0:
        indice_co = indice_eq
    conservador = candidatos[indice_co]

    # Los tres escenarios deben ser distintos y separados, si no el
    # cliente ve el mismo precio dos veces (pasaba cuando el optimo caia en 78%).
    _pct_eq = min(94, int(equilibrado["porcentaje_tope"]))
    _pct_ag = max(78, _pct_eq - 4)
    if _pct_eq - _pct_ag < 2:
        _pct_eq = min(99, _pct_ag + 2)
    _pct_co = min(99, _pct_eq + 5)
    if _pct_co - _pct_eq < 3:
        _pct_co = min(99, _pct_eq + 3)
    if _pct_co <= _pct_ag:
        _pct_co = min(99, _pct_ag + 4)
    agresivo = candidatos[max(0, min(len(candidatos) - 1, _pct_ag - 78))]
    equilibrado = candidatos[max(0, min(len(candidatos) - 1, _pct_eq - 78))]
    conservador = candidatos[max(0, min(len(candidatos) - 1, _pct_co - 78))]

    def _justificar(nombre, esc):
        return (
            f"{nombre}: oferta del {esc['porcentaje_tope']}% del tope "
            f"(${esc['total_bruto_clp']:,} CLP con IVA). Margen {esc['margen_pct']}% "
            f"(${esc['margen_clp']:,} CLP sobre un costo de ${esc['costo_interno_clp']:,} CLP). "
            f"Puntaje estimado {esc['puntaje_estimado']}/100 y probabilidad de adjudicar "
            f"{esc['prob_adjudicacion_pct']}%. Supuestos: peso del precio "
            f"{int(peso_precio*100)}%, competencia al {int(pct_competencia*100)}% del tope, "
            f"{competidores} oferentes."
        )

    aviso = ""
    if equilibrado["margen_pct"] < margen_objetivo * 100.0:
        aviso = (f" ADVERTENCIA: el margen objetivo de {int(margen_objetivo*100)}% no es "
                 f"alcanzable en este proceso; el máximo lograble es {equilibrado['margen_pct']}%.")

    agresivo["justificacion"] = _justificar("Oferta competitiva", agresivo) + aviso
    equilibrado["justificacion"] = _justificar("Oferta recomendada", equilibrado) + aviso
    conservador["justificacion"] = _justificar("Oferta conservadora", conservador) + aviso
    for esc in (agresivo, equilibrado, conservador):
        esc["estrategia"] = esc["justificacion"]

    sensibilidad = []
    for pct in (0.80, 0.84, 0.88, 0.92, 0.96, 0.99):
        e = evaluar(pct)
        sensibilidad.append({
            "porcentaje_tope": e["porcentaje_tope"],
            "total_bruto_clp": e["total_bruto_clp"],
            "margen_pct": e["margen_pct"],
            "margen_clp": e["margen_clp"],
            "puntaje_estimado": e["puntaje_estimado"],
            "prob_adjudicacion_pct": e["prob_adjudicacion_pct"],
        })

    return {
        "presupuesto_oficial_tope_bruto_clp": presupuesto,
        "neto_maximo_oficial_clp": int(round(presupuesto / 1.19)),
        "costo_interno_clp": costo,
        "parametros": {
            "costo_sobre_tope": costo_ratio,
            "margen_objetivo_pct": round(margen_objetivo * 100, 1),
            "peso_precio_pct": round(peso_precio * 100, 1),
            "pct_competencia": round(pct_competencia * 100, 1),
            "competidores_estimados": competidores,
        },
        "escenario_1_competitivo_agresivo": agresivo,
        "escenario_2_equilibrado_recomendado": equilibrado,
        "escenario_3_premium_alta_gama": conservador,
        "sensibilidad": sensibilidad,
        "regla_calculo": ("Recorre 78%-99% del tope; estima probabilidad de adjudicar según el "
                          "precio de la competencia y maximiza margen x probabilidad."),
    }


_RESUMEN_ESCANEO = {"ca_fallos": 0, "ca_ok": 0, "lic_abiertas": 0, "lic_candidatos": 0}


NOTIFICAR_ENTREGAS = [True]


def _notificaciones_activas():
    """True si esta corrida debe mandar correo y WhatsApp."""
    return bool(NOTIFICAR_ENTREGAS[0])


def _extracto_para_ia(texto, limite=None):
    """Arma un recorte repartido entre los documentos clave.

    Antes se tomaban los primeros N caracteres del informe, así que la IA leía
    completo el primer documento y nada de los demás. Ahora se da una cuota a
    cada documento, priorizando EETT, bases, BAE y formularios.
    """
    _tope_defecto = str(IA_PREMIUM_TOPE_TEXTO) if PREMIUM_ACTIVO else "8000"
    limite = int(limite or os.getenv("MAX_TEXTO_PROMPT", _tope_defecto))
    texto = texto or ""
    partes = texto.split("=== [LECTURA FORENSE COMPLETA:")
    if len(partes) <= 1:
        return texto[:limite]

    documentos = []
    for parte in partes[1:]:
        cabecera, _, resto = parte.partition("]")
        nombre = cabecera.strip()
        if "(Metodo:" in nombre:
            nombre = nombre.split("(Metodo:")[0].strip()
        cuerpo = resto.split("=== [FIN ADJUNTO:")[0].strip()
        if len(cuerpo) < 150:
            continue
        nombre_upper = nombre.upper()
        peso = 0
        for clave, valor in (("EETT", 3), ("TECNIC", 3), ("BASES", 3), ("BAE", 3),
                             ("ADMINISTRATIV", 2), ("FORMATO", 2), ("ANEXO", 2)):
            if clave in nombre_upper:
                peso = max(peso, valor)
        documentos.append((peso, nombre, cuerpo))

    if not documentos:
        return texto[:limite]

    documentos.sort(key=lambda x: -x[0])
    cuota = max(1200, limite // max(1, min(len(documentos), 4)))
    bloques = []
    for peso, nombre, cuerpo in documentos[:4]:
        bloques.append(f"--- {nombre} ---\n{cuerpo[:cuota]}")
    return "\n\n".join(bloques)[:limite]


def _deduplicar_adjuntos(rutas):
    """Quita adjuntos repetidos (mismo contenido) que dejan los reprocesos.

    Cada reproceso vuelve a bajar el anexo con otro nombre (Hosting.xlsx,
    Hosting_2.xlsx, ...). Se conserva el primero y se borran los clones.
    """
    import hashlib as _hl
    vistos = {}
    limpias = []
    for ruta in rutas or []:
        try:
            if not os.path.isfile(ruta):
                continue
            with open(ruta, "rb") as f:
                firma = _hl.sha256(f.read()).hexdigest()
        except Exception:
            limpias.append(ruta)
            continue
        if firma in vistos:
            try:
                os.remove(ruta)
                print(f"      ♻️ Adjunto repetido descartado: {os.path.basename(ruta)}")
            except Exception:
                pass
            continue
        vistos[firma] = ruta
        limpias.append(ruta)
    return limpias


def _lineas_documento(informe, nombre_doc, limite=10):
    """Devuelve las líneas con contenido real de UN documento del informe forense.

    Sirve para que la sección 7 muestre los ítems exactos que pide el organismo
    (por ejemplo los de una planilla Excel), sin depender de cómo los reescriba la IA.
    """
    informe = informe or ""
    objetivo = str(nombre_doc or "").strip().lower()
    if not objetivo:
        return []
    for parte in informe.split("=== [LECTURA FORENSE COMPLETA:")[1:]:
        cabecera, _, resto = parte.partition("]")
        nombre = cabecera.split("(Metodo:")[0].strip()
        if nombre.strip().lower() != objetivo:
            continue
        cuerpo = resto.split("=== [FIN ADJUNTO:")[0]
        lineas = []
        for cruda in cuerpo.split("\n"):
            limpia = cruda.replace("|", " ").replace("*", " ")
            limpia = " ".join(limpia.split()).strip(" .-:;")
            if len(limpia) < 4:
                continue
            letras = sum(1 for c in limpia if c.isalpha())
            if letras < 4 or letras / max(1, len(limpia)) < 0.55:
                continue
            if 'metodo:' in limpia.lower() or limpia.startswith('('):
                continue
            if limpia.lower() in [x.lower() for x in lineas]:
                continue
            lineas.append(limpia)
            if len(lineas) >= limite:
                break
        return lineas
    return []


def _estado_compra_agil_texto():
    """Texto corto del estado de Compra Ágil para el resumen."""
    fallos = _RESUMEN_ESCANEO.get("ca_fallos") or 0
    ok = _RESUMEN_ESCANEO.get("ca_ok") or 0
    if fallos and not ok:
        return f"portal sin respuesta ({fallos} consultas con error)"
    if ok:
        return f"{ok} de tu giro"
    if fallos:
        return f"sin coincidencias (con {fallos} avisos del portal)"
    return "revisada, sin coincidencias con tu giro"


def _mensaje_sin_novedades():
    """Arma el aviso de 'no hay nada hoy', distinguiendo falla técnica de falta de ofertas."""
    ahora = _ahora_chile()
    lineas = [f"🤖 *LICITAIA* · {ahora:%d-%m-%Y} {ahora:%H:%M}", ""]
    lineas.append("Sin proyectos nuevos para tu giro en esta corrida.")
    lineas.append("")
    lineas.append("*Qué se revisó*")
    if _RESUMEN_ESCANEO.get("ca_fallos"):
        lineas.append(f"• Compra Ágil: el portal *no respondió* "
                      f"({_RESUMEN_ESCANEO['ca_fallos']} consultas con error). "
                      f"No significa que no haya ofertas.")
    else:
        lineas.append("• Compra Ágil: revisada, sin coincidencias con tu giro.")
    lineas.append(f"• Licitaciones: {_RESUMEN_ESCANEO.get('lic_abiertas', 0)} abiertas, "
                  f"{_RESUMEN_ESCANEO.get('lic_candidatos', 0)} de tu rubro.")
    lineas.append("")
    lineas.append("Se vuelve a revisar en la próxima corrida programada.")
    return "\n".join(lineas)


