# ==============================================================================
# AGENTE 2.5: ESPECIALISTA FORENSE EN LECTURA MULTIMODAL DE ADJUNTOS (IA GEMINI)
# ==============================================================================
class Agente2_5LectorForense:
    """
    Lector Forense Multimodal de nivel industrial. Para cada adjunto descargado:
    1. Extrae texto hoja-por-hoja con pdfplumber (tablas+texto), pypdf, python-docx y openpyxl.
    2. Envia el PDF binario directamente a Gemini como parte multimodal (application/pdf).
    3. Genera un Word clon CLON_EXACTO_ADJUNTO_[nombre].docx con todo el contenido forense.
    4. Devuelve un informe forense consolidado que el Agente 3 DEBE usar 100%.
    """

    def __init__(self, perfil):
        self.perfil = perfil
        self.url_gemini_upload = "https://generativelanguage.googleapis.com/upload/v1beta/files"
        self.url_gemini_gen = f"https://generativelanguage.googleapis.com/v1beta/models/{MODELO_GEMINI}:generateContent?key={API_KEY_GEMINI}"

    def _extraer_texto_pdfplumber(self, ruta_pdf):
        """Extrae texto Y tablas hoja por hoja de PDF con pdfplumber."""
        if pdfplumber is None:
            return ""
        textos = []
        try:
            with pdfplumber.open(ruta_pdf) as pdf:
                for i, page in enumerate(pdf.pages, 1):
                    txt_pg = page.extract_text() or ""
                    tablas = page.extract_tables() or []
                    bloque = f"[Pag.{i}]"
                    if txt_pg.strip():
                        bloque += " " + txt_pg.strip()
                    for tabla in tablas:
                        for fila in tabla:
                            celdas = [str(c or "").strip() for c in fila if c]
                            if celdas:
                                bloque += "\n  " + " | ".join(celdas)
                    textos.append(bloque)
        except Exception as e:
            textos.append(f"(pdfplumber error: {e})")
        return "\n".join(textos)

    def _extraer_texto_pypdf(self, ruta_pdf):
        """Fallback pypdf para texto plano."""
        if pypdf is None:
            return ""
        textos = []
        try:
            reader = pypdf.PdfReader(ruta_pdf)
            for i, page in enumerate(reader.pages, 1):
                t = page.extract_text() or ""
                if t.strip():
                    textos.append(f"[Pag.{i}]: {t.strip()}")
        except Exception as e:
            textos.append(f"(pypdf error: {e})")
        return "\n".join(textos)

    def _extraer_texto_word(self, ruta_docx):
        """Extrae texto completo + todas las tablas de un Word."""
        textos = []
        try:
            d = Document(ruta_docx)
            for p in d.paragraphs:
                if p.text.strip():
                    textos.append(p.text.strip())
            for idx_t, tabla in enumerate(d.tables, 1):
                textos.append(f"[Tabla {idx_t}]")
                for row in tabla.rows:
                    celdas = [c.text.strip() for c in row.cells if c.text.strip()]
                    if celdas:
                        textos.append("  " + " | ".join(celdas))
        except Exception as e:
            print(f"      [!] Word no legible ({os.path.basename(ruta_docx)}): {str(e)[:60]}")
            textos = self._extraer_texto_doc_antiguo(ruta_docx) or textos
        return "\n".join(textos)

    def _extraer_texto_doc_antiguo(self, ruta_doc):
        """Lee los .doc de Word 97-2003 con antiword o catdoc."""
        for comando in (["antiword", "-w", "0", ruta_doc],
                        ["catdoc", "-w", ruta_doc]):
            try:
                r = subprocess.run(comando, capture_output=True, timeout=60)
                salida = (r.stdout or b"").decode("utf-8", "ignore").strip()
                if len(salida) > 100:
                    print(f"      📖 [TEXTO EXTRAÍDO .doc ANTIGUO] "
                          f"{os.path.basename(ruta_doc)}: {len(salida)} chars")
                    return salida
            except FileNotFoundError:
                continue
            except Exception:
                continue
        print(f"      [!] .doc antiguo sin convertidor: {os.path.basename(ruta_doc)}")
        return ""

    def _extraer_texto_excel(self, ruta_xlsx):
        """Extrae TODAS las hojas y celdas del Excel."""
        textos = []
        try:
            wb = openpyxl.load_workbook(ruta_xlsx, data_only=True)
            for sname in wb.sheetnames:
                ws = wb[sname]
                filas_hoja = []
                for row in ws.iter_rows(values_only=True):
                    vals = [str(v).strip() for v in row if v is not None and str(v).strip()]
                    if vals:
                        filas_hoja.append(" | ".join(vals))
                if filas_hoja:
                    textos.append(f"[Hoja: {sname}]\n" + "\n".join(filas_hoja))
        except Exception as e:
            textos.append(f"(excel error: {e})")
        return "\n".join(textos)

    def _leer_pdf_por_partes(self, ruta_pdf, nombre_archivo, paginas_por_bloque=10):
        """Parte un PDF enorme en bloques y los lee por separado.

        Un PDF de 12 MB no alcanza a procesarse en una sola llamada (timeout de
        300s): se trocea con pypdf y se concatena el resultado.
        """
        try:
            import pypdf
            lector = pypdf.PdfReader(ruta_pdf)
            total_paginas = len(lector.pages)
        except Exception as e:
            print(f"      [!] No se pudo abrir el PDF para trocearlo: {e}")
            return ""
        if total_paginas <= paginas_por_bloque:
            return ""
        print(f"      ✂️ PDF grande ({total_paginas} páginas): se lee en bloques de {paginas_por_bloque}")
        import tempfile
        partes = []
        for inicio in range(0, total_paginas, paginas_por_bloque):
            ruta_parte = ""
            try:
                escritor = pypdf.PdfWriter()
                for pagina in lector.pages[inicio:inicio + paginas_por_bloque]:
                    escritor.add_page(pagina)
                with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tmp:
                    escritor.write(tmp.name)
                    ruta_parte = tmp.name
                fin = min(inicio + paginas_por_bloque, total_paginas)
                etiqueta = f"{nombre_archivo} (paginas {inicio + 1}-{fin})"
                texto = self._leer_pdf_con_gemini_multimodal(ruta_parte, etiqueta)
                if texto:
                    partes.append(f"--- {etiqueta} ---\n{texto}")
            except Exception as e:
                print(f"      [!] Error leyendo el bloque {inicio + 1}: {str(e)[:70]}")
            finally:
                if ruta_parte:
                    try:
                        os.remove(ruta_parte)
                    except Exception:
                        pass
        if partes:
            print(f"      ✅ [2.5] {nombre_archivo}: {len(partes)} bloque(s) leídos")
        return "\n\n".join(partes)

    def _leer_pdf_con_vision(self, ruta_pdf, nombre="", max_paginas=4):
        """Lee un PDF escaneado enviando las paginas como imagen a un modelo con vision.

        Usa el proveedor compatible con OpenAI (DeepSeek Flash acepta imagenes).
        Devuelve el texto reconocido o "" si no se pudo.
        """
        url = (os.getenv("IA_VISION_URL", "").strip().rstrip("/")
               or (IA_PREMIUM_URL if PREMIUM_ACTIVO else IA_BASE_URL))
        clave = (os.getenv("IA_VISION_KEY", "").strip()
                 or (IA_PREMIUM_KEY if PREMIUM_ACTIVO else IA_API_KEY))
        modelo = (os.getenv("IA_VISION_MODELO", "").strip()
                  or (IA_PREMIUM_MODELO if PREMIUM_ACTIVO else IA_MODELO))
        if not url or not clave or not modelo:
            return ""
        try:
            try:
                import pymupdf as fitz
            except Exception:
                import fitz
            import base64
        except Exception as e:
            print(f"      [!] Vision IA no disponible: {str(e)[:60]}")
            return ""
        try:
            documento = fitz.open(ruta_pdf)
        except Exception as e:
            print(f"      [!] Vision IA: no se pudo abrir {nombre}: {str(e)[:50]}")
            return ""

        imagenes = []
        try:
            for indice in range(min(max_paginas, documento.page_count)):
                pagina = documento.load_page(indice)
                pix = pagina.get_pixmap(dpi=150)
                imagenes.append(base64.b64encode(pix.tobytes("png")).decode("ascii"))
        except Exception as e:
            print(f"      [!] Vision IA: error renderizando paginas: {str(e)[:50]}")
            return ""
        finally:
            try:
                documento.close()
            except Exception:
                pass

        if not imagenes:
            return ""

        contenido = [{
            "type": "text",
            "text": ("Transcribe este documento en espanol tal como esta escrito. "
                     "Manten titulos, numeracion, tablas (usa | entre columnas) y cifras. "
                     "No resumas ni interpretes: solo transcribe el texto que ves."),
        }]
        for b64 in imagenes:
            contenido.append({
                "type": "image_url",
                "image_url": {"url": f"data:image/png;base64,{b64}"},
            })

        payload = {
            "model": modelo,
            "messages": [{"role": "user", "content": contenido}],
            "temperature": 0.0,
            "max_tokens": 4096,
        }
        try:
            print(f"      👁️ Vision IA ({modelo}): leyendo {len(imagenes)} pagina(s) de {nombre}...")
            r = requests.post(url + "/chat/completions", json=payload,
                              headers={"Authorization": f"Bearer {clave}",
                                       "Content-Type": "application/json"},
                              timeout=300)
            if r.status_code != 200:
                print(f"      [!] Vision IA HTTP {r.status_code}: {(r.text or '')[:120]}")
                return ""
            datos = r.json() or {}
            opciones = datos.get("choices") or []
            if not opciones:
                return ""
            texto = ((opciones[0].get("message") or {}).get("content") or "").strip()
            if len(texto) > 100:
                print(f"      OK Vision IA: {len(texto)} caracteres recuperados")
                return texto
        except Exception as e:
            print(f"      [!] Vision IA fallo: {str(e)[:80]}")
        return ""

    def _leer_pdf_con_gemini_multimodal(self, ruta_pdf, nombre_archivo):
        if _ia_limite_alcanzado():
            print("      [!] Cuota de IA agotada: se extrae el texto sin IA")
            return ""
        # Caché por huella: si el PDF ya se transcribió, no se vuelve a leer
        try:
            with open(ruta_pdf, "rb") as _f_cache:
                _huella = hashlib.sha256(_f_cache.read()).hexdigest()[:32]
            _dir_cache = os.path.join(DIRECTORIO_RAIZ, "cache_textos")
            os.makedirs(_dir_cache, exist_ok=True)
            _ruta_cache = os.path.join(_dir_cache, _huella + ".txt")
            if os.path.isfile(_ruta_cache):
                with open(_ruta_cache, encoding="utf-8") as _f_cache:
                    _texto_guardado = _f_cache.read()
                if len(_texto_guardado) > 200:
                    print(f"      ♻️ {nombre_archivo}: transcripción reutilizada (caché)")
                    return _texto_guardado
        except Exception:
            pass
        # PDFs gigantes: se trocean para que Gemini los lea completos
        try:
            _tam_pdf = os.path.getsize(ruta_pdf)
        except OSError:
            _tam_pdf = 0
        if _tam_pdf > 8 * 1024 * 1024:
            _texto_partes = self._leer_pdf_por_partes(ruta_pdf, nombre_archivo)
            if _texto_partes:
                return _texto_partes

        """
        Envia el PDF binario directamente a Gemini como parte multimodal.
        Usa la File API para subir y luego generateContent con mime_type=application/pdf.
        """
        if not API_KEY_GEMINI:
            return ""
        try:
            # Subir archivo a File API
            with open(ruta_pdf, "rb") as f_bin:
                pdf_bytes = f_bin.read()

            tam_mb = len(pdf_bytes) / (1024 * 1024)
            print(f"      🤖 [Agente 2.5 Gemini] Subiendo {nombre_archivo} ({tam_mb:.1f} MB) a Gemini File API...")

            # Upload con resumable upload
            headers_upload = {"Content-Type": "application/pdf"}
            r_up = requests.post(
                f"{self.url_gemini_upload}?key={API_KEY_GEMINI}&uploadType=media",
                headers=headers_upload,
                data=pdf_bytes,
                timeout=180
            )
            if r_up.status_code not in [200, 201]:
                return ""

            file_data = r_up.json()
            file_uri = file_data.get("file", {}).get("uri", "")
            if not file_uri:
                return ""

            print(f"      🤖 [Agente 2.5 Gemini] Archivo subido. Enviando prompt forense hoja por hoja...")

            prompt_forense = f"""Eres un Lector Forense Especialista en Documentos de Contratacion Publica Chilena.
Lee el documento adjunto HOJA POR HOJA y extrae el 100% de su contenido tecnico.

INSTRUCCION ESTRICTA: NO omitas NINGUNA informacion del documento. Debes extraer y transcribir:
1. Cada item solicitado con su descripcion completa, cantidad exacta y unidad de medida.
2. Especificaciones tecnicas detalladas (medidas, formatos, resolucion, alcance, canales, medios).
3. Plan de medios, pautas, cronogramas, distribuciones por canal si los hay.
4. Plazos de entrega, hitos de entrega, fechas fatales.
5. Multas, penalizaciones y requisitos excluyentes.
6. Tablas completas (trascribelas fila por fila con sus columnas).
7. Anexos tecnicos, bases administrativas y cualquier especificacion adicional.

NOMBRE DEL ARCHIVO: {nombre_archivo}
Lee y transcribe el contenido completo en formato estructurado."""

            payload_gen = {
                "contents": [{
                    "parts": [
                        {"file_data": {"mime_type": "application/pdf", "file_uri": file_uri}},
                        {"text": prompt_forense}
                    ]
                }],
                "generationConfig": {"temperature": 0.1, "max_output_tokens": 8192}
            }
            r_gen = None
            for _intento_lect in (1, 2):
                try:
                    r_gen = requests.post(self.url_gemini_gen, json=payload_gen, timeout=300)
                except Exception as e_up:
                    print(f"      [!] Reintento {_intento_lect} de lectura multimodal "
                          f"({nombre_archivo}): {str(e_up)[:80]}")
                    r_gen = None
                    if _intento_lect == 1:
                        time.sleep(5)
                    continue
                if r_gen.status_code == 200:
                    break
                print(f"      [!] Gemini respondió {r_gen.status_code} leyendo {nombre_archivo}")
                if _intento_lect == 1:
                    time.sleep(8)
            if r_gen is not None and r_gen.status_code == 200:
                txt = r_gen.json().get("candidates", [{}])[0].get("content", {}).get("parts", [{}])[0].get("text", "")
                if txt:
                    print(f"      ✅ [Agente 2.5 Gemini Multimodal] {len(txt)} chars extraidos de {nombre_archivo}")
                    try:
                        with open(ruta_pdf, "rb") as _f_cache:
                            _huella = hashlib.sha256(_f_cache.read()).hexdigest()[:32]
                        _dir_cache = os.path.join(DIRECTORIO_RAIZ, "cache_textos")
                        os.makedirs(_dir_cache, exist_ok=True)
                        with open(os.path.join(_dir_cache, _huella + ".txt"), "w",
                                  encoding="utf-8") as _f_cache:
                            _f_cache.write(txt)
                    except Exception:
                        pass
                    return txt
        except Exception as e:
            print(f"      [!] Gemini File API error para {nombre_archivo}: {e}")
        return ""

    def _resumen_documental(self, nombre, texto):
        """Resumen estructurado de UN documento, para el informe del cliente.

        Devuelve dict con: archivo, objeto, requisitos, excluyentes, riesgos,
        preguntas. Si la IA falla, devuelve None (el informe sigue funcionando).
        """
        recorte = (texto or "")[:5000]
        if len(recorte.strip()) < 150:
            return None
        if os.getenv("RESUMENES_IA", "0").strip() != "1":
            return None
        if _ia_limite_alcanzado():
            print("      [!] Cuota de IA agotada: se usa el resumen extractivo")
            return None
        prompt = (
            "Eres abogado e ingeniero experto en contratacion publica chilena "
            "(Ley 19.886, DS 661/2024, Ley 21.634). Analiza ESTE documento de un "
            "proceso de Mercado Publico con el maximo detalle util para ofertar.\n"
            "Responde SOLO JSON valido, sin markdown, con esta forma exacta:\n"
            '{"objeto": "que exige el documento, en dos o tres frases concretas", '
            '"requisitos": ["requisito obligatorio, con la cifra o plazo que exija"], '
            '"excluyentes": ["causal de inadmisibilidad, citando la clausula si aparece"], '
            '"documentos_obligatorios": ["documento que el oferente debe presentar"], '
            '"criterios_evaluacion": ["criterio y su peso o puntaje si lo indica"], '
            '"plazos": ["plazo, hito o fecha relevante"], '
            '"garantias": ["garantia exigida: tipo, monto y vigencia"], '
            '"multas": ["multa o sancion con su formula o monto si aparece"], '
            '"riesgos": ["riesgo concreto para el oferente, explicado"], '
            '"observaciones": ["clausula dudosa, ambigua o contraria a la ley, con el articulo"], '
            '"preguntas": ["pregunta lista para el foro de consultas"]}\n'
            "Reglas: hasta 10 elementos por lista; cita cifras, plazos, articulos y "
            "numeros de clausula cuando existan; si el documento no trata un tema, "
            "devuelve esa lista vacia; no inventes nada que no este en el texto.\n\n"
            f"DOCUMENTO: {nombre}\n"
            f"CONTENIDO:\n{recorte}"
        )
        datos, error = _gemini_generar_json(prompt, temperatura=0.1, max_tokens=2200,
                                            timeout=360, intentos=3, premium=True)
        if not datos:
            print(f"      [!] Sin resumen de {nombre}: {str(error)[:80]}")
            return None

        def _lista(clave):
            valor = datos.get(clave) or []
            if isinstance(valor, str):
                valor = [valor]
            return [str(v)[:400] for v in valor if str(v).strip()][:10]

        salida = {
            "archivo": nombre,
            "objeto": str(datos.get("objeto") or "")[:600],
            "requisitos": _lista("requisitos"),
            "excluyentes": _lista("excluyentes"),
            "documentos_obligatorios": _lista("documentos_obligatorios"),
            "criterios_evaluacion": _lista("criterios_evaluacion"),
            "plazos": _lista("plazos"),
            "garantias": _lista("garantias"),
            "multas": _lista("multas"),
            "riesgos": _lista("riesgos"),
            "observaciones": _lista("observaciones"),
            "preguntas": _lista("preguntas"),
        }
        print(f"      Resumen de {nombre}: {len(salida['requisitos'])} requisitos, "
              f"{len(salida['excluyentes'])} excluyentes")
        return salida

    def _extraer_texto_ocr(self, ruta_pdf, max_paginas=40):
        """OCR local con Tesseract: gratis, sin cuota y sin internet.

        Es la vía para los PDF escaneados (EETT, BAE) que no tienen capa de
        texto: se renderiza cada página y se reconoce el texto en español.
        """
        try:
            try:
                import pymupdf as fitz
            except Exception:
                import fitz  # pymupdf version antigua
            import pytesseract
            from PIL import Image
            from io import BytesIO
        except Exception as e:
            print(f"      [!] OCR no disponible en este contenedor: {str(e)[:60]}")
            return ""
        try:
            documento = fitz.open(ruta_pdf)
        except Exception as e:
            print(f"      [!] OCR: no se pudo abrir el PDF: {str(e)[:60]}")
            return ""
        total = min(len(documento), int(max_paginas))
        print(f"      🔎 OCR local: {total} página(s) de {os.path.basename(ruta_pdf)[:48]}")
        partes = []
        for numero in range(total):
            try:
                pagina = documento.load_page(numero)
                pix = pagina.get_pixmap(dpi=200)
                imagen = Image.open(BytesIO(pix.tobytes("png")))
                texto_pagina = pytesseract.image_to_string(imagen, lang="spa")
                if texto_pagina and texto_pagina.strip():
                    partes.append(texto_pagina.strip())
            except Exception as e:
                print(f"      [!] OCR falló en la página {numero + 1}: {str(e)[:50]}")
        try:
            documento.close()
        except Exception:
            pass
        resultado = "\n".join(partes)
        if resultado:
            print(f"      ✅ OCR local: {len(resultado)} caracteres recuperados")
        return resultado

    def resumenes_diferidos(self, expediente):
        """Genera los resúmenes por documento DESPUÉS de la auditoría principal.

        Motivo: los proveedores gratuitos limitan los tokens por minuto. Si los
        resúmenes se piden antes, consumen la cuota y el Agente 3 (el dossier y
        la auditoría de multas) se queda sin turno.
        """
        texto = (expediente.get("informe_forense_adjuntos")
                 or expediente.get("texto_extraido_adjuntos") or "")
        if not texto:
            return []
        salida = []
        for parte in texto.split("=== [LECTURA FORENSE COMPLETA:")[1:]:
            cabecera, _, resto = parte.partition("]")
            nombre = cabecera.strip()
            if "(Metodo:" in nombre:
                nombre = nombre.split("(Metodo:")[0].strip()
            if not nombre or nombre.upper().startswith("FICHA_TEXTO_"):
                continue
            cuerpo = resto.split("=== [FIN ADJUNTO:")[0].strip()
            if len(cuerpo) < 250 or len(salida) >= 6:
                continue
            resumen = self._resumen_documental(nombre, cuerpo)
            if resumen:
                salida.append(resumen)
        print(f"   ✓ [2.5] {len(salida)} resumen(es) de documento generados")
        return salida

    def leer_adjuntos_forense(self, lista_rutas, carpeta_proyecto):
        """
        Proceso forense completo para todos los adjuntos.
        Retorna un dict con:
          - informe_forense_consolidado: texto completo para Agente 3
          - archivos_clon_generados: lista de paths de los Word clones
          - nombres_adjuntos_leidos: lista de nombres de archivos citados
        """
        print(f"\n🔬 [AGENTE 2.5] LECTURA FORENSE MULTIMODAL DE {len(lista_rutas)} ADJUNTOS...")
        informe_bloques = []
        archivos_clon = []
        nombres_leidos = []
        resumenes_docs = []

        # Filtrar solo archivos con contenido real (no clones anteriores ni DOM txt para PDF-lectura)
        rutas_a_leer = [r for r in lista_rutas if os.path.exists(r) and not os.path.basename(r).startswith("CLON_EXACTO_")]

        for ruta in rutas_a_leer:
            nom = os.path.basename(ruta)
            ext = os.path.splitext(ruta)[1].lower()
            if nom.startswith("ANEXO_CLON_BASES_OFICIALES_"):
                continue

            texto_extraido = ""
            metodo_usado = "ninguno"

            if ext == ".pdf":
                # 1) Texto embebido en el PDF (rapido y sin costo)
                texto_plumber = self._extraer_texto_pdfplumber(ruta)
                if texto_plumber and len(texto_plumber) > 1200:
                    texto_extraido = texto_plumber
                    metodo_usado = "pdfplumber"
                else:
                    # 2) OCR local para escaneados (gratis, sin cuota)
                    texto_ocr = self._extraer_texto_ocr(ruta)
                    if texto_ocr and len(texto_ocr) > 300:
                        texto_extraido = texto_ocr
                        metodo_usado = "OCR local (tesseract)"
                    else:
                        # 3) Vision IA (DeepSeek Flash acepta imagenes)
                        texto_vision = self._leer_pdf_con_vision(ruta, nom)
                        if texto_vision and len(texto_vision) > 100:
                            texto_extraido = texto_vision
                            metodo_usado = "Vision IA"
                        else:
                            # 4) Respaldo: Gemini multimodal
                            texto_gemini = self._leer_pdf_con_gemini_multimodal(ruta, nom)
                            if texto_gemini and len(texto_gemini) > 100:
                                texto_extraido = texto_gemini
                                metodo_usado = "Gemini-Multimodal"
                            else:
                                texto_extraido = self._extraer_texto_pypdf(ruta)
                                metodo_usado = "pypdf"

            elif ext in [".docx", ".doc"]:
                texto_extraido = self._extraer_texto_word(ruta)
                metodo_usado = "python-docx"

            elif ext in [".xlsx", ".xls"]:
                texto_extraido = self._extraer_texto_excel(ruta)
                metodo_usado = "openpyxl"

            elif ext == ".txt":
                try:
                    texto_extraido = open(ruta, encoding="utf-8", errors="ignore").read()
                    metodo_usado = "texto-plano"
                except Exception:
                    pass

            if texto_extraido and len(texto_extraido.strip()) > 50:
                bloque = (
                    f"=== [LECTURA FORENSE COMPLETA: {nom}] (Metodo: {metodo_usado}) ===\n"
                    f"{texto_extraido.strip()}\n"
                    f"=== [FIN ADJUNTO: {nom}] ==="
                )
                informe_bloques.append(bloque)
                nombres_leidos.append(nom)
                if os.getenv("RESUMENES_INLINE", "0") == "1" and len(texto_extraido) > 800 and len(resumenes_docs) < 8:
                    _res = self._resumen_documental(nom, texto_extraido)
                    if _res:
                        resumenes_docs.append(_res)
                print(f"      ✅ [2.5 Forense] {nom}: {len(texto_extraido)} chars ({metodo_usado})")

                # (no se genera clon Word: el adjunto original ya está en la carpeta)
            else:
                # Si no se pudo leer, intenta Gemini con DOM txt si existe
                print(f"      [!] [2.5 Forense] No se pudo leer contenido de: {nom}")
                informe_bloques.append(f"[ADJUNTO SIN CONTENIDO EXTRAIBLE: {nom}]")

        informe_consolidado = "\n\n".join(informe_bloques)
        print(f"   ✅ [Agente 2.5] Informe forense: {len(informe_consolidado)} chars | {len(archivos_clon)} clones Word generados")

        return {
            "informe_forense_consolidado": informe_consolidado,
            "archivos_clon_generados": archivos_clon,
            "nombres_adjuntos_leidos": nombres_leidos,
            "resumenes_documentos": resumenes_docs
        }

    def _generar_clon_word(self, nombre_archivo, texto_forense, metodo, ruta_docx):
        """
        Genera un Word clon estructurado con diseño oficial que replica
        hoja por hoja todo el contenido forense extraido del adjunto.
        """
        try:
            doc = Document()
            for s in doc.sections:
                s.top_margin = Inches(0.65)
                s.bottom_margin = Inches(0.65)
                s.left_margin = Inches(0.75)
                s.right_margin = Inches(0.75)

            # Banner
            t_ban = doc.add_table(rows=1, cols=1)
            t_ban.alignment = WD_TABLE_ALIGNMENT.CENTER
            c_ban = t_ban.rows[0].cells[0]
            c_ban._tc.get_or_add_tcPr().append(parse_xml(f'<w:shd {nsdecls("w")} w:fill="0F172A"/>'))
            p_b = c_ban.paragraphs[0]
            p_b.alignment = WD_ALIGN_PARAGRAPH.CENTER
            p_b.paragraph_format.space_before = Pt(6)
            p_b.paragraph_format.space_after = Pt(4)
            r_b1 = p_b.add_run(f"CLON EXACTO DE ADJUNTO OFICIAL - LECTURA FORENSE\n")
            r_b1.bold = True
            r_b1.font.size = Pt(12)
            r_b1.font.color.rgb = RGBColor(255, 255, 255)
            r_b2 = p_b.add_run(f"Archivo Fuente: {nombre_archivo} | Metodo: {metodo}")
            r_b2.font.size = Pt(9)
            r_b2.font.color.rgb = RGBColor(148, 163, 184)

            doc.add_paragraph().paragraph_format.space_after = Pt(4)

            # Contenido forense hoja por hoja
            secciones = texto_forense.split("[Pag.")
            if len(secciones) > 1:
                # Dividir por paginas detectadas
                for sec in secciones:
                    if not sec.strip():
                        continue
                    p_sec = doc.add_paragraph()
                    idx_fin = sec.find("]")
                    if idx_fin > 0:
                        num_pag = sec[:idx_fin].strip()
                        contenido_pag = sec[idx_fin+1:].strip()
                        r_hdr = p_sec.add_run(f"Pagina {num_pag}")
                        r_hdr.bold = True
                        r_hdr.font.size = Pt(10)
                        r_hdr.font.color.rgb = RGBColor(30, 58, 138)
                        p_cont = doc.add_paragraph()
                        r_cont = p_cont.add_run(contenido_pag[:8000])
                        r_cont.font.size = Pt(9)
                    else:
                        p_sec.add_run(sec[:8000]).font.size = Pt(9)
            else:
                # Contenido sin paginacion detectada
                fragmentos = [texto_forense[i:i+6000] for i in range(0, min(len(texto_forense), 36000), 6000)]
                for idx_f, frag in enumerate(fragmentos, 1):
                    p_frag = doc.add_paragraph()
                    if len(fragmentos) > 1:
                        r_hdr = p_frag.add_run(f"Seccion {idx_f}:")
                        r_hdr.bold = True
                        r_hdr.font.size = Pt(10)
                        r_hdr.font.color.rgb = RGBColor(30, 58, 138)
                        doc.add_paragraph().add_run(frag).font.size = Pt(9)
                    else:
                        p_frag.add_run(frag).font.size = Pt(9)

            # Pie
            p_pie = doc.add_paragraph()
            p_pie.alignment = WD_ALIGN_PARAGRAPH.CENTER
            p_pie.paragraph_format.space_before = Pt(12)
            r_pie = p_pie.add_run(
                f"Clon Forense Oficial B2G · Mantytech SpA · "
                f"Generado el {datetime.datetime.now().strftime('%d-%m-%Y %H:%M')}"
            )
            r_pie.font.size = Pt(8)
            r_pie.font.color.rgb = RGBColor(148, 163, 184)

            doc.save(ruta_docx)
            print(f"      📄 [Agente 2.5] Clon Word generado: {os.path.basename(ruta_docx)}")
        except Exception as e:
            print(f"      [!] Error generando Clon Word {os.path.basename(ruta_docx)}: {e}")


