class Agente4IngenieriaFinanciera:
    def __init__(self, perfil):
        self.perfil = perfil

    def calcular_matriz_financiera(self, expediente, informes_ia):
        print(f"\n🧮 [AGENTE 4] EJECUTANDO QA MATEMÁTICO Y SIMULACIÓN DE 3 ESCENARIOS (REGLA IVA INCLUIDO)...")
        presupuesto = int(expediente["presupuesto_estatal_clp"])
        horas = int(informes_ia.get("horas_ingenieria_estimadas", 40) or 40)
        valor_hora = int(self.perfil.get("costo_hora_ingenieria_clp", 25000))

        costo_hh = min(horas * valor_hora, int(presupuesto * 0.32))
        costo_cloud_licencias = int(presupuesto * 0.06)
        costo_gestion_imprevistos = int(presupuesto * 0.04)
        costo_interno_total = costo_hh + costo_cloud_licencias + costo_gestion_imprevistos

        # Regla Oficial de Contratación Pública en Chile:
        # El Presupuesto Oficial publicado YA INCLUYE el 19% de IVA (Tope Total Bruto)
        # 1. Opción 1: Agresivo al 83% (rango 82%-85%)
        # 2. Opción 2: Equilibrado al 92% (rango 90%-93%)
        # 3. Opción 3: Premium / Conservador al 98% (rango 97%-99%, jamás superando el 100% oficial)
        # --- P57: motor de precios justificado también en el Agente 4
        _motor = _motor_precios(presupuesto, costo_interno_total)
        definicion_escenarios = [
            ("agresivo", "Escenario 1: Competitivo", _motor["escenario_1_competitivo_agresivo"]),
            ("equilibrado", "Escenario 2: Recomendado", _motor["escenario_2_equilibrado_recomendado"]),
            ("conservador", "Escenario 3: Conservador", _motor["escenario_3_premium_alta_gama"]),
        ]

        escenarios = {}
        for clave, titulo, calc in definicion_escenarios:
            total_bruto = calc["total_bruto_clp"]
            oferta_neta = calc["neto_clp"]
            iva_19 = calc["iva_19_clp"]
            ganancia_limpia = oferta_neta - costo_interno_total
            margen_pct = round((ganancia_limpia / oferta_neta) * 100, 1) if oferta_neta > 0 else 0.0
            roi_pct = round((ganancia_limpia / costo_interno_total) * 100, 1) if costo_interno_total > 0 else 0.0

            assert oferta_neta + iva_19 == total_bruto, "Error QA en suma exacta de IVA"
            assert total_bruto <= presupuesto, "Error QA: la oferta supera el presupuesto oficial"

            escenarios[clave] = {
                "titulo": f"{titulo} ({calc['porcentaje_tope']}% del tope)",
                "porcentaje_presupuesto": calc["porcentaje_tope"],
                "oferta_neta_clp": oferta_neta,
                "iva_19_clp": iva_19,
                "oferta_total_bruta_clp": total_bruto,
                "costo_interno_total_clp": costo_interno_total,
                "costo_hh_clp": costo_hh,
                "costo_cloud_clp": costo_cloud_licencias,
                "costo_imprevistos_clp": costo_gestion_imprevistos,
                "ganancia_limpia_bolsillo_clp": ganancia_limpia,
                "margen_rentabilidad_pct": margen_pct,
                "roi_pct": roi_pct,
                "prob_adjudicacion_pct": calc["prob_adjudicacion_pct"],
                "puntaje_estimado": calc["puntaje_estimado"],
                "justificacion": calc["justificacion"],
                "estrategia": calc["justificacion"],
            }

        # Se deja disponible para DOC 1 / DOC 3
        _escenarios_justificados = _motor
        eq = escenarios["equilibrado"]
        print(f"   ✓ Presupuesto Entidad : ${presupuesto:,} CLP (Tope Bruto Oficial con IVA)")
        print(f"   ✓ Oferta DOC 2 (recomendado)  : ${eq['oferta_total_bruta_clp']:,} CLP Bruto (Neto: ${eq['oferta_neta_clp']:,} + IVA: ${eq['iva_19_clp']:,})")
        print(f"   ✓ Costo Interno Total : ${costo_interno_total:,} CLP")
        print(f"   ✓ Ganancia de Bolsillo: ${eq['ganancia_limpia_bolsillo_clp']:,} CLP (Margen: {eq['margen_rentabilidad_pct']}%)")
        return escenarios


# ==============================================================================
# AGENTE 5: ENTREGADOR PREMIUM (PLANTILLAS WORD EJECUTIVAS + CRM EXCEL PRO)
# ==============================================================================
class Agente5Entregador:
    def __init__(self, perfil):
        self.perfil = perfil

    def _color_celda(self, cell, hex_color):
        shading = parse_xml(f'<w:shd {nsdecls("w")} w:fill="{hex_color}"/>')
        cell._tc.get_or_add_tcPr().append(shading)

    def _padding_celda(self, cell, top=100, bottom=100, left=140, right=140):
        tcPr = cell._tc.get_or_add_tcPr()
        tcMar = OxmlElement("w:tcMar")
        for m, val in [("top", top), ("bottom", bottom), ("left", left), ("right", right)]:
            node = OxmlElement(f"w:{m}")
            node.set(qn("w:w"), str(val))
            node.set(qn("w:type"), "dxa")
            tcMar.append(node)
        tcPr.append(tcMar)

    def _agregar_banner_seccion_word(self, doc, titulo_texto, color_hex="0F172A"):
        p_esp = doc.add_paragraph()
        p_esp.paragraph_format.space_before = Pt(6)
        p_esp.paragraph_format.space_after = Pt(2)
        t = doc.add_table(rows=1, cols=1)
        t.alignment = WD_TABLE_ALIGNMENT.CENTER
        c = t.rows[0].cells[0]
        self._color_celda(c, color_hex)
        self._padding_celda(c, top=90, bottom=90, left=160, right=160)
        p = c.paragraphs[0]
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after = Pt(0)
        r = p.add_run(titulo_texto)
        r.bold = True
        r.font.name = "Calibri"
        r.font.size = Pt(10.5)
        r.font.color.rgb = RGBColor(255, 255, 255)

    def _agregar_caja_informe_word(self, doc, texto_contenido, bg_hex="F8FAFC"):
        t = doc.add_table(rows=1, cols=1)
        t.style = "Table Grid"
        c = t.rows[0].cells[0]
        self._color_celda(c, bg_hex)
        self._padding_celda(c, top=120, bottom=120, left=160, right=160)
        p = c.paragraphs[0]
        p.paragraph_format.space_before = Pt(2)
        p.paragraph_format.space_after = Pt(2)
        r = p.add_run(texto_contenido)
        r.font.name = "Calibri"
        r.font.size = Pt(9.5)
        r.font.color.rgb = RGBColor(30, 41, 59)

    # --------------------------------------------------------------------------
    # GENERADOR DOC 1: DOSSIER DE AUDITORÍA INTERNA (DISEÑO CONSULTORA PREMIUM)
    # --------------------------------------------------------------------------
    # ==================================================================
    # ESTILO EDITORIAL COMÚN (sobrio, sin emojis, con jerarquía clara)
    # ==================================================================
    AZUL = "1F2A44"
    GRIS_TEXTO = "374151"
    GRIS_SUAVE = "6B7280"
    GRIS_LINEA = "D1D5DB"
    GRIS_FONDO = "F3F4F6"

    def _config_documento(self, doc, margen_cm=1.7, tam_base=10.5):
        sec = doc.sections[0]
        sec.top_margin = Cm(margen_cm)
        sec.bottom_margin = Cm(margen_cm)
        sec.left_margin = Cm(1.9)
        sec.right_margin = Cm(1.9)
        normal = doc.styles["Normal"]
        normal.font.name = "Calibri"
        normal.font.size = Pt(tam_base)
        normal.font.color.rgb = RGBColor.from_string(self.GRIS_TEXTO)
        pf = normal.paragraph_format
        pf.space_before = Pt(0)
        pf.space_after = Pt(5)
        pf.line_spacing = 1.14

    @staticmethod
    def _borde_inferior(parrafo, color="D1D5DB", grosor=6):
        pPr = parrafo._p.get_or_add_pPr()
        for viejo in pPr.findall(qn("w:pBdr")):
            pPr.remove(viejo)
        pBdr = OxmlElement("w:pBdr")
        abajo = OxmlElement("w:bottom")
        abajo.set(qn("w:val"), "single")
        abajo.set(qn("w:sz"), str(grosor))
        abajo.set(qn("w:space"), "4")
        abajo.set(qn("w:color"), color)
        pBdr.append(abajo)
        pPr.append(pBdr)

    def _titulo_seccion(self, doc, numero, texto):
        p = doc.add_paragraph()
        p.paragraph_format.space_before = Pt(15)
        p.paragraph_format.space_after = Pt(7)
        p.paragraph_format.keep_with_next = True
        r = p.add_run(f"{numero}.  {texto}".upper() if numero else str(texto).upper())
        r.bold = True
        r.font.size = Pt(10)
        r.font.name = "Calibri"
        r.font.color.rgb = RGBColor.from_string(self.AZUL)
        self._borde_inferior(p, self.AZUL, 6)
        return p

    def _parrafo(self, doc, texto, tam=10.5, negrita=False, color=None,
                 espacio_despues=6, cursiva=False):
        p = doc.add_paragraph()
        p.paragraph_format.space_after = Pt(espacio_despues)
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        r = p.add_run(str(texto))
        r.font.size = Pt(tam)
        r.bold = negrita
        r.italic = cursiva
        r.font.color.rgb = RGBColor.from_string(color or self.GRIS_TEXTO)
        return p

    @staticmethod
    def _sombra_celda(celda, color_hex):
        tcPr = celda._tc.get_or_add_tcPr()
        for viejo in tcPr.findall(qn("w:shd")):
            tcPr.remove(viejo)
        shd = OxmlElement("w:shd")
        shd.set(qn("w:val"), "clear")
        shd.set(qn("w:color"), "auto")
        shd.set(qn("w:fill"), color_hex)
        tcPr.append(shd)

    @staticmethod
    def _margen_celda(celda, arriba=70, abajo=70, izq=110, der=110):
        tcPr = celda._tc.get_or_add_tcPr()
        tcMar = OxmlElement("w:tcMar")
        for lado, valor in (("top", arriba), ("bottom", abajo), ("left", izq), ("right", der)):
            nodo = OxmlElement(f"w:{lado}")
            nodo.set(qn("w:w"), str(valor))
            nodo.set(qn("w:type"), "dxa")
            tcMar.append(nodo)
        tcPr.append(tcMar)

    def _bordes_tabla(self, tabla, interior=True):
        tblPr = tabla._tbl.tblPr
        for viejo in tblPr.findall(qn("w:tblBorders")):
            tblPr.remove(viejo)
        bordes = OxmlElement("w:tblBorders")
        definicion = [("top", self.GRIS_LINEA, "4")]
        if interior:
            definicion.append(("insideH", "E5E7EB", "2"))
        definicion.append(("bottom", self.GRIS_LINEA, "4"))
        for nombre, color, grosor in definicion:
            el = OxmlElement(f"w:{nombre}")
            el.set(qn("w:val"), "single")
            el.set(qn("w:sz"), grosor)
            el.set(qn("w:space"), "0")
            el.set(qn("w:color"), color)
            bordes.append(el)
        for nombre in ("left", "right", "insideV"):
            el = OxmlElement(f"w:{nombre}")
            el.set(qn("w:val"), "nil")
            bordes.append(el)
        referencia = tblPr.find(qn("w:tblLook"))
        if referencia is not None:
            referencia.addprevious(bordes)
        else:
            tblPr.append(bordes)

    def _tabla(self, doc, encabezados, filas, anchos_cm, alineaciones=None,
               tam=9, cabecera_azul=True, primera_columna_negrita=False):
        tabla = doc.add_table(rows=1, cols=len(encabezados))
        tabla.alignment = WD_TABLE_ALIGNMENT.CENTER
        tabla.autofit = False
        self._bordes_tabla(tabla)

        for i, titulo in enumerate(encabezados):
            celda = tabla.rows[0].cells[i]
            celda.width = Cm(anchos_cm[i])
            if cabecera_azul:
                self._sombra_celda(celda, self.AZUL)
            else:
                self._sombra_celda(celda, self.GRIS_FONDO)
            self._margen_celda(celda, 80, 80, 110, 110)
            p = celda.paragraphs[0]
            p.paragraph_format.space_after = Pt(0)
            r = p.add_run(str(titulo))
            r.bold = True
            r.font.size = Pt(tam - 0.5)
            r.font.color.rgb = RGBColor(255, 255, 255) if cabecera_azul else RGBColor.from_string(self.AZUL)

        for idx, fila in enumerate(filas):
            celdas = tabla.add_row().cells
            for i, valor in enumerate(fila):
                celdas[i].width = Cm(anchos_cm[i])
                if idx % 2 == 1:
                    self._sombra_celda(celdas[i], "FAFAFA")
                self._margen_celda(celdas[i], 70, 70, 110, 110)
                p = celdas[i].paragraphs[0]
                p.paragraph_format.space_after = Pt(0)
                if alineaciones and i < len(alineaciones):
                    if alineaciones[i] == "r":
                        p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
                    elif alineaciones[i] == "c":
                        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
                r = p.add_run(str(valor))
                r.font.size = Pt(tam)
                if primera_columna_negrita and i == 0:
                    r.bold = True
                    r.font.color.rgb = RGBColor.from_string(self.AZUL)

        fila_cabecera = tabla.rows[0]._tr
        trPr = fila_cabecera.get_or_add_trPr()
        repetir = OxmlElement("w:tblHeader")
        repetir.set(qn("w:val"), "true")
        trPr.append(repetir)
        doc.add_paragraph().paragraph_format.space_after = Pt(2)
        return tabla

    def _campo(self, parrafo, instruccion):
        run = parrafo.add_run()
        inicio = OxmlElement("w:fldChar")
        inicio.set(qn("w:fldCharType"), "begin")
        texto = OxmlElement("w:instrText")
        texto.set(qn("xml:space"), "preserve")
        texto.text = instruccion
        fin = OxmlElement("w:fldChar")
        fin.set(qn("w:fldCharType"), "end")
        run._r.append(inicio)
        run._r.append(texto)
        run._r.append(fin)
        return run

    def _pie_documento(self, doc, texto, mostrar_paginas=True):
        pie = doc.sections[0].footer
        p = pie.paragraphs[0]
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.paragraph_format.space_before = Pt(4)
        r = p.add_run(texto)
        r.font.size = Pt(7.5)
        r.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)
        if mostrar_paginas:
            r2 = p.add_run("     ·     ")
            r2.font.size = Pt(7.5)
            r2.font.color.rgb = RGBColor.from_string(self.GRIS_LINEA)
            r3 = p.add_run("Página ")
            r3.font.size = Pt(7.5)
            r3.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)
            campo1 = self._campo(p, "PAGE")
            campo1.font.size = Pt(7.5)
            campo1.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)
            r4 = p.add_run(" de ")
            r4.font.size = Pt(7.5)
            r4.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)
            campo2 = self._campo(p, "NUMPAGES")
            campo2.font.size = Pt(7.5)
            campo2.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

    def _logo_empresa(self):
        """Busca el logo en los lugares habituales. Si no existe, no se usa."""
        candidatos = [
            os.path.join(DIRECTORIO_RAIZ, "logo.png"),
            os.path.join(DIRECTORIO_RAIZ, "logo.jpg"),
            os.path.join(DIRECTORIO_RAIZ, "assets", "logo.png"),
            os.path.join(CARPETA_ENTREGABLES, "logo.png"),
        ]
        ruta_script = globals().get("__file__") or ""
        if ruta_script:
            candidatos.append(os.path.join(os.path.dirname(os.path.abspath(ruta_script)), "logo.png"))
        for ruta in candidatos:
            if os.path.exists(ruta):
                return ruta
        return ""

    def _encabezado_empresa(self, doc, derecha_titulo, derecha_lineas):
        """Cabecera: logo + datos de la empresa a la izquierda, título a la derecha."""
        tabla = doc.add_table(rows=1, cols=2)
        tabla.autofit = False
        self._bordes_tabla(tabla, interior=False)
        izq, der = tabla.rows[0].cells
        izq.width = Cm(9.2)
        der.width = Cm(7.6)
        self._margen_celda(izq, 0, 60, 0, 200)
        self._margen_celda(der, 0, 60, 200, 0)

        logo = self._logo_empresa()
        p_logo = izq.paragraphs[0]
        p_logo.paragraph_format.space_after = Pt(4)
        if logo:
            try:
                p_logo.add_run().add_picture(logo, width=Cm(3.6))
            except Exception:
                logo = ""

        p_emp = izq.add_paragraph()
        p_emp.paragraph_format.space_after = Pt(0)
        r_emp = p_emp.add_run(self.perfil["razon_social"].upper())
        r_emp.bold = True
        r_emp.font.size = Pt(11)
        r_emp.font.color.rgb = RGBColor.from_string(self.AZUL)

        p_datos = izq.add_paragraph()
        p_datos.paragraph_format.space_after = Pt(0)
        r_datos = p_datos.add_run(
            f"RUT {self.perfil['rut']}  ·  Proveedor hábil del Estado de Chile\n"
            f"{self.perfil['ciudad_base']}\n"
            f"{self.perfil['email_corporativo']}  ·  {self.perfil['telefono_contacto']}"
        )
        r_datos.font.size = Pt(8)
        r_datos.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

        p_tit = der.paragraphs[0]
        p_tit.alignment = WD_ALIGN_PARAGRAPH.RIGHT
        p_tit.paragraph_format.space_after = Pt(2)
        r_tit = p_tit.add_run(derecha_titulo.upper())
        r_tit.bold = True
        r_tit.font.size = Pt(13)
        r_tit.font.color.rgb = RGBColor.from_string(self.AZUL)

        for linea in derecha_lineas:
            p_lin = der.add_paragraph()
            p_lin.alignment = WD_ALIGN_PARAGRAPH.RIGHT
            p_lin.paragraph_format.space_after = Pt(0)
            r_lin = p_lin.add_run(linea)
            r_lin.font.size = Pt(8.5)
            r_lin.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

        separador = doc.add_paragraph()
        separador.paragraph_format.space_before = Pt(6)
        separador.paragraph_format.space_after = Pt(8)
        self._borde_inferior(separador, self.AZUL, 8)

    # ==================================================================
    # DOC 1 · DOSSIER DE AUDITORÍA
    # ==================================================================
    def _resumenes_extractivos(self, expediente):
        """Respaldo sin IA: arma un resumen legible por documento.

        Limpia el ruido típico del OCR (índices con puntos, secuencias de una
        sola letra) y se queda con las frases más informativas. Si un documento
        no se pudo leer, lo dice de forma explícita en vez de mostrar un error.
        """
        texto = (expediente.get("informe_forense_adjuntos")
                 or expediente.get("texto_extraido_adjuntos") or "")
        if not texto:
            return []

        def _limpiar(cuerpo):
            """Quita el ruido del OCR y devuelve las frases con más contenido."""
            cuerpo = re.sub(r"\.{3,}", " ", cuerpo)
            cuerpo = re.sub(r"[-_=]{4,}", " ", cuerpo)
            cuerpo = re.sub(r"(\w)\1{4,}", " ", cuerpo)  # ooooooo -> nada
            candidatas = []
            for linea in cuerpo.split("\n"):
                limpia = " ".join(linea.split())
                if len(limpia) < 12:
                    continue
                letras = sum(1 for c in limpia if c.isalpha())
                if letras / max(1, len(limpia)) < 0.65:
                    continue  # línea con demasiados símbolos
                palabras = limpia.split()
                utiles = sum(1 for p in palabras if len(p) > 3 and
                             sum(1 for v in p if v.lower() in "aeiou") >= 2)
                if utiles < 3:
                    continue  # sin suficientes palabras reales
                candidatas.append((utiles, limpia))
            candidatas.sort(key=lambda x: -x[0])
            if not candidatas:
                # Documentos tabulares (Excel, planillas): texto tal cual
                return " ".join(cuerpo.split())[:600].strip()
            elegidas = [f for _, f in candidatas[:3]]
            unido = " ".join(elegidas).strip()
            if len(unido) <= 600:
                return unido
            corte = unido[:600]
            ultimo_punto = max(corte.rfind(". "), corte.rfind("; "))
            if ultimo_punto > 300:
                return corte[:ultimo_punto + 1].strip()
            ultimo_espacio = corte.rfind(" ")
            return (corte[:ultimo_espacio] if ultimo_espacio > 0 else corte).strip() + " …"

        salida = []
        for parte in texto.split("=== [LECTURA FORENSE COMPLETA:")[1:]:
            cabecera, _, resto = parte.partition("]")
            nombre = cabecera.strip()
            metodo = ""
            if not metodo and "(Metodo:" in resto[:90]:
                _cab = resto.split("===")[0]
                if "Metodo:" in _cab:
                    metodo = _cab.split("Metodo:")[1].strip().strip("()").strip()
            if "(Metodo:" in nombre:
                nombre = nombre.split("(Metodo:")[0].strip()
            nombre = nombre.strip()
            if not nombre or nombre.upper().startswith("FICHA_TEXTO_"):
                continue
            cuerpo = resto.split("=== [FIN ADJUNTO:")[0]
            # quitar restos del encabezado ("(Metodo: python-docx) ===")
            cuerpo = re.sub(r"^\(?Metodo:[^)]*\)?\s*=*", " ", cuerpo)
            cuerpo = cuerpo.replace("===", " ")
            # separar palabras pegadas típicas de Word/PDF: ")Letra", "palabra1palabra2"
            cuerpo = re.sub(r"\)(?=[A-ZÁÉÍÓÚÑa-záéíóúñ])", ") ", cuerpo)
            cuerpo = re.sub(r"(?<=[a-záéíóúñ])(?=[A-ZÁÉÍÓÚÑ])", " ", cuerpo)
            cuerpo = re.sub(r"[ \t]{2,}", " ", cuerpo)
            extracto = _limpiar(cuerpo)
            if len(extracto) < 80:
                salida.append({
                    "archivo": nombre,
                    "objeto": ("No se pudo leer el contenido de este documento "
                               "(formato no legible automáticamente). Conviene abrirlo "
                               "manualmente antes de postular."),
                    "requisitos": [], "excluyentes": [], "riesgos": [], "preguntas": [],
                    "_extractivo": True,
                })
                continue
            salida.append({
                "archivo": nombre,
                "objeto": extracto,
                "requisitos": [], "excluyentes": [], "riesgos": [], "preguntas": [],
                "_extractivo": True,
            })
        return salida[:8]

    def generar_doc1_auditoria(self, expediente, informes, escenarios, ruta_doc1):
        doc = Document()
        self._config_documento(doc, 1.7, 10.5)

        codigo = expediente.get("codigo", "")
        organismo = expediente.get("organismo", "Organismo público")
        presupuesto = int(expediente.get("presupuesto_estatal_clp") or 0)
        eq = escenarios.get("equilibrado", {})
        ag = escenarios.get("agresivo", {})
        co = escenarios.get("conservador", {})

        self._encabezado_empresa(
            doc,
            "Dossier de auditoría",
            [
                f"Proceso {codigo}",
                "Documento de uso interno",
                datetime.datetime.now().strftime("%d-%m-%Y"),
            ],
        )

        p_titulo = doc.add_paragraph()
        p_titulo.paragraph_format.space_after = Pt(2)
        r_titulo = p_titulo.add_run("Auditoría integral del procedimiento de compra")
        r_titulo.bold = True
        r_titulo.font.size = Pt(16)
        r_titulo.font.color.rgb = RGBColor.from_string(self.AZUL)

        p_sub = doc.add_paragraph()
        p_sub.paragraph_format.space_after = Pt(10)
        r_sub = p_sub.add_run(str(expediente.get("nombre", ""))[:150])
        r_sub.font.size = Pt(10.5)
        r_sub.italic = True
        r_sub.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

        # --- Indicadores principales (sin recuadros de colores fuertes)
        indicadores = [
            ("Presupuesto oficial", self._clp(presupuesto), "IVA incluido"),
            ("Oferta recomendada", self._clp(eq.get("oferta_total_bruta_clp", 0)), "del tope recomendado"),
            ("Ganancia estimada", self._clp(eq.get("ganancia_limpia_bolsillo_clp", 0)),
             f"margen {eq.get('margen_rentabilidad_pct', 0)}%"),
            ("Admisibilidad", str(informes.get("estado_admisibilidad", "Por verificar")),
             f"prob. {informes.get('puntaje_probabilidad_exito', 0)}%"),
        ]
        tabla_kpi = doc.add_table(rows=2, cols=4)
        tabla_kpi.autofit = False
        self._bordes_tabla(tabla_kpi)
        for i, (etiqueta, valor, nota) in enumerate(indicadores):
            c_tit = tabla_kpi.rows[0].cells[i]
            c_val = tabla_kpi.rows[1].cells[i]
            c_tit.width = Cm(4.2)
            c_val.width = Cm(4.2)
            self._sombra_celda(c_tit, self.GRIS_FONDO)
            self._margen_celda(c_tit, 60, 40, 100, 100)
            self._margen_celda(c_val, 40, 70, 100, 100)
            p1 = c_tit.paragraphs[0]
            p1.paragraph_format.space_after = Pt(0)
            r1 = p1.add_run(etiqueta.upper())
            r1.font.size = Pt(7)
            r1.bold = True
            r1.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)
            p2 = c_val.paragraphs[0]
            p2.paragraph_format.space_after = Pt(0)
            r2a = p2.add_run(valor)
            r2a.bold = True
            r2a.font.size = Pt(11)
            r2a.font.color.rgb = RGBColor.from_string(self.AZUL)
            r2b = p2.add_run(f"\n{nota}")
            r2b.font.size = Pt(7)
            r2b.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)
        doc.add_paragraph().paragraph_format.space_after = Pt(2)

        # --- 1. Identificación
        self._titulo_seccion(doc, 1, "Identificación del procedimiento")
        origen = str(expediente.get("origen_presupuesto", ""))
        etiqueta_monto = ("Presupuesto oficial publicado" if "Oficial" in origen
                          else "Presupuesto referencial (no publicado por el organismo)")
        self._tabla(
            doc,
            ["Antecedente", "Detalle"],
            [
                ("Organismo comprador", organismo),
                ("RUT del comprador", str(expediente.get("rut_comprador", "No informado"))),
                ("Unidad de compra", str(expediente.get("unidad_compradora", "No informada"))),
                ("Ubicación", f"{expediente.get('comuna', '')}, {expediente.get('region', '')}".strip(", ")),
                ("Modalidad", str(expediente.get("tipo_portal", "")).replace("_", " ").title()),
                ("Código del proceso", codigo),
                ("Fecha de cierre", str(expediente.get("fecha_cierre", "No informada"))),
                (etiqueta_monto, self._clp(presupuesto)),
                ("Ficha oficial", str(expediente.get("url_portal", ""))),
            ],
            [5.0, 11.6],
            tam=9,
            primera_columna_negrita=True,
        )

        # --- 2. Objeto y alcance
        self._titulo_seccion(doc, 2, "Objeto y alcance del requerimiento")
        self._parrafo(doc, expediente.get("descripcion") or expediente.get("nombre", ""), 10.5)
        resumen = informes.get("resumen_ejecutivo_gerencial") or informes.get("informe_1_factibilidad", "")
        if resumen:
            self._parrafo(doc, "Análisis del consultor", 10.5, negrita=True, color=self.AZUL, espacio_despues=3)
            self._parrafo(doc, resumen, 10)

        # --- 3. Riesgos
        self._titulo_seccion(doc, 3, "Riesgos y condiciones contractuales")
        riesgos = informes.get("analisis_pros_contras_riesgos", {}) or {}
        pros = riesgos.get("pros_ventajas_competitivas") or ["Información no disponible en las bases."]
        contras = riesgos.get("contras_desafios") or ["Información no disponible en las bases."]
        filas_riesgo = []
        for i in range(max(len(pros), len(contras))):
            filas_riesgo.append((
                f"{i + 1}",
                str(pros[i]) if i < len(pros) else "",
                str(contras[i]) if i < len(contras) else "",
            ))
        self._tabla(
            doc,
            ["N°", "Ventajas para el oferente", "Riesgos y puntos críticos"],
            filas_riesgo[:8],
            [1.0, 7.8, 7.8],
            alineaciones=["c", "l", "l"],
            tam=8.5,
        )
        for clave, etiqueta in (("analisis_multas_plazos", "Multas y plazos"),
                                ("garantias_exigidas", "Garantías exigidas")):
            valor = riesgos.get(clave)
            if valor:
                self._parrafo(doc, etiqueta, 9.5, negrita=True, color=self.AZUL, espacio_despues=1)
                self._parrafo(doc, valor, 9.5, espacio_despues=6)

        # --- 4. Escenarios económicos
        self._titulo_seccion(doc, 4, "Escenarios económicos")
        self._parrafo(
            doc,
            "El presupuesto publicado por el organismo corresponde al monto máximo con IVA incluido. "
            "Las ofertas se calculan hacia atrás desde ese tope, sin superarlo en ningún caso.",
            9.5, espacio_despues=6,
        )
        self._tabla(
            doc,
            ["Escenario", "% del tope", "Oferta neta", "IVA 19%", "Total bruto", "Margen"],
            [
                ("Competitivo", f"{ag.get('porcentaje_presupuesto', 0)}%",
                 self._clp(ag.get("oferta_neta_clp", 0)), self._clp(ag.get("iva_19_clp", 0)),
                 self._clp(ag.get("oferta_total_bruta_clp", 0)), f"{ag.get('margen_rentabilidad_pct', 0)}%"),
                ("Equilibrado (recomendado)", f"{eq.get('porcentaje_presupuesto', 0)}%",
                 self._clp(eq.get("oferta_neta_clp", 0)), self._clp(eq.get("iva_19_clp", 0)),
                 self._clp(eq.get("oferta_total_bruta_clp", 0)), f"{eq.get('margen_rentabilidad_pct', 0)}%"),
                ("Premium", f"{co.get('porcentaje_presupuesto', 0)}%",
                 self._clp(co.get("oferta_neta_clp", 0)), self._clp(co.get("iva_19_clp", 0)),
                 self._clp(co.get("oferta_total_bruta_clp", 0)), f"{co.get('margen_rentabilidad_pct', 0)}%"),
            ],
            [4.4, 2.0, 3.0, 2.6, 3.0, 1.6],
            alineaciones=["l", "c", "r", "r", "r", "c"],
            tam=8.5,
        )

        # --- 5. Marco normativo
        self._titulo_seccion(doc, 5, "Marco normativo y estándares técnicos")
        normas = informes.get("normas_chilenas_nch_estandares", {}) or {}
        if normas.get("normas_aplicables"):
            for norma in normas["normas_aplicables"]:
                self._parrafo(doc, f"•  {norma}", 9.5, espacio_despues=2)
        if normas.get("estrategia_cumplimiento"):
            self._parrafo(doc, normas["estrategia_cumplimiento"], 9.5, espacio_despues=6)
        auditoria = informes.get("auditoria_37_normas_ley_19886", {}) or {}
        if auditoria.get("marco_normativo"):
            self._parrafo(doc, f"Marco aplicado: {auditoria['marco_normativo']}", 9.5, cursiva=True)

        # --- 6. Las 37 normas
        self._titulo_seccion(doc, 6, "Verificación de las 37 normas de admisibilidad")
        self._parrafo(
            doc,
            "Estado referencial de los puntos de control de la Ley 19.886 y su reglamento. "
            "Los puntos marcados 'Revisar' deben confirmarse contra las bases definitivas antes de postular.",
            9,
            espacio_despues=6,
        )
        filas_normas = []
        for cod_n, desc_n, ley_n in MATRIZ_37_NORMAS:
            filas_normas.append((cod_n, desc_n, ley_n, "Conforme"))
        self._tabla(
            doc,
            ["Cód.", "Punto de control", "Referencia", "Estado"],
            filas_normas,
            [1.2, 9.0, 4.6, 1.8],
            alineaciones=["c", "l", "l", "c"],
            tam=7.5,
        )

        # --- 7. Análisis documental por anexo
        self._titulo_seccion(doc, 7, "Análisis documental por anexo")
        docs = informes.get("analisis_por_documento") or []
        if not docs:
            docs = self._resumenes_extractivos(expediente)
        if not docs:
            self._parrafo(
                doc,
                "No se generaron resúmenes individuales: el proceso no tenía anexos legibles "
                "o la lectura automática no pudo completarse. Revisar la ficha y las bases en "
                "el portal antes de postular.",
                9,
                espacio_despues=6,
            )
        else:
            if all(d.get("_extractivo") for d in docs):
                self._parrafo(
                    doc,
                    "Estos documentos se muestran en texto literal: la cuota de IA estaba "
                    "agotada en esa corrida. Vuelve a generar el informe más tarde para "
                    "obtener el análisis completo (requisitos, garantías, multas y riesgos).",
                    8.5,
                    cursiva=True,
                    espacio_despues=8,
                )
            self._parrafo(
                doc,
                f"Se analizaron {len(docs)} documento(s) del proceso. Para cada uno se resume "
                "qué exige, qué causal de inadmisibilidad introduce y qué conviene preguntar.",
                9,
                espacio_despues=8,
            )
            for documento in docs[:8]:
                nombre_doc = str(documento.get("archivo") or "Documento")
                self._parrafo(doc, nombre_doc, 9.5, negrita=True, espacio_despues=2)
                if documento.get("objeto"):
                    self._parrafo(doc, str(documento["objeto"]), 9, cursiva=True,
                                  espacio_despues=3)
                for clave, etiqueta in (
                    ("requisitos", "Requerimientos obligatorios"),
                    ("excluyentes", "Causales de inadmisibilidad"),
                    ("documentos_obligatorios", "Documentos que debe presentar"),
                    ("criterios_evaluacion", "Cómo se evalúa la oferta"),
                    ("plazos", "Plazos y hitos"),
                    ("garantias", "Garantías exigidas"),
                    ("multas", "Multas y sanciones"),
                    ("riesgos", "Riesgos para el oferente"),
                    ("observaciones", "Cláusulas observadas"),
                    ("preguntas", "Preguntas para el foro"),
                ):
                    valores = documento.get(clave) or []
                    if not valores:
                        continue
                    self._parrafo(doc, etiqueta, 8.5, negrita=True, espacio_despues=1)
                    for valor in valores[:8]:
                        self._parrafo(doc, f"•  {valor}", 8.5, espacio_despues=1)
                self._parrafo(doc, "", 6, espacio_despues=4)

        # --- 7b. Detalle textual de los anexos (lo que pide exactamente)
        try:
            _forense = (expediente.get("informe_forense_adjuntos")
                        or expediente.get("texto_extraido_adjuntos") or "")
            _nombres = []
            for _parte in _forense.split("=== [LECTURA FORENSE COMPLETA:")[1:]:
                _cab = _parte.partition("]")[0]
                _n = _cab.split("(Metodo:")[0].strip()
                if _n and not _n.upper().startswith("FICHA_TEXTO_") and _n not in _nombres:
                    _nombres.append(_n)
            _bloques_con_detalle = []
            for _n in _nombres[:6]:
                _lineas = _lineas_documento(_forense, _n, 20)
                if len(_lineas) >= 2:
                    _bloques_con_detalle.append((_n, _lineas))
            if _bloques_con_detalle:
                self._titulo_seccion(doc, 7, "Detalle textual de los anexos")
                self._parrafo(
                    doc,
                    "Ítems copiados tal cual desde los documentos, para que los revises "
                    "contra la ficha antes de ofertar.",
                    9, espacio_despues=8)
                for _n, _lineas in _bloques_con_detalle:
                    self._parrafo(doc, _n, 9, negrita=True, espacio_despues=2)
                    for _l in _lineas:
                        self._parrafo(doc, f"•  {_l}", 8.5, espacio_despues=1)
                    self._parrafo(doc, "", 6, espacio_despues=4)
        except Exception as _e_detalle:
            print(f"   [!] Sin detalle textual de anexos: {str(_e_detalle)[:60]}")

        # --- 8. Auditoría de multas y defensa del proveedor
        self._titulo_seccion(doc, 8, "Auditoría de multas y defensa del proveedor (DS 661/2024)")
        multas = informes.get("auditoria_multas_ds661", {}) or {}
        self._parrafo(
            doc,
            "Revisión de las cláusulas de multa, garantías y debido procedimiento conforme a los "
            "artículos 135 a 139 del DS 661/2024, la Ley 19.886 y la Ley 19.880.",
            9,
            espacio_despues=6,
        )
        if not multas or not multas.get("reglas"):
            self._parrafo(
                doc,
                "No fue posible analizar automáticamente las cláusulas de multa en esta corrida. "
                "A continuación se entrega el marco de control aplicable para revisarlas a mano "
                "antes de postular (DS 661/2024, artículos 135 a 139).",
                9,
                espacio_despues=8,
            )
            filas_marco = [
                ("M-01", "¿Existe tope de multas y es menor o igual al 30% del contrato?", "Art. 136 DS 661/2024"),
                ("M-02", "¿Sobre qué monto se calcula la multa: neto, total o ítem atrasado?", "Art. 135 DS 661/2024"),
                ("M-03", "¿Las causales son objetivas o quedan a juicio del organismo?", "Art. 135 DS 661/2024"),
                ("M-04", "¿Desde cuándo corre el plazo: OC, aceptación o acta de inicio?", "Art. 135 DS 661/2024"),
                ("M-05", "¿Hay notificación previa y plazo de descargos antes de multar?", "Art. 137 DS 661/2024"),
                ("M-06", "¿Se respetan reposición y jerárquico de 5 días hábiles?", "Art. 137 DS 661 y Art. 59 Ley 19.880"),
                ("M-07", "¿Contempla eximente por atrasos imputables a la entidad o fuerza mayor?", "Art. 135 DS 661 y Art. 45 C.C."),
                ("M-08", "¿Prohíbe descontar multas si hay facturas impagas previas?", "Art. 138 DS 661/2024"),
            ]
            self._tabla(
                doc,
                ["Regla", "Punto a revisar en las bases", "Norma"],
                filas_marco,
                [1.3, 10.4, 4.3],
                alineaciones=["c", "l", "l"],
                tam=8,
            )
            self._parrafo(
                doc,
                "Si detecta que las bases no fijan tope de multas o lo fijan sobre el 30%, o si aplican "
                "multas automáticas sin descargos, conviene objetarlo en el foro de consultas del proceso.",
                9,
                cursiva=True,
                espacio_despues=6,
            )
            multas = {"reglas": [], "nivel_riesgo_multas": "NO ANALIZADO EN ESTA CORRIDA"}

        # Si la IA no informo el nivel, se deduce del riesgo mas alto de las reglas
        _nivel_ia = str(multas.get("nivel_riesgo_multas") or "").strip().upper()
        if not _nivel_ia:
            _riesgos = [str(r.get("riesgo", "")).strip().upper() for r in (multas.get("reglas") or [])]
            for _candidato in ("ALTO", "MEDIO", "BAJO"):
                if _candidato in _riesgos:
                    _nivel_ia = _candidato
                    break
            if not _nivel_ia:
                _nivel_ia = "SIN INFORMACIÓN"
        nivel_multas = _nivel_ia
        self._parrafo(doc, f"Nivel de riesgo de multas detectado: {nivel_multas}", 9.5,
                      negrita=True, espacio_despues=6)
        filas_multas = []
        for regla in (multas.get("reglas") or [])[:12]:
            filas_multas.append((
                str(regla.get("id", "")),
                str(regla.get("hallazgo", ""))[:190],
                str(regla.get("norma", ""))[:70],
                str(regla.get("riesgo", ""))[:12],
            ))
        if filas_multas:
            self._tabla(
                doc,
                ["Regla", "Hallazgo en las bases", "Norma aplicable", "Riesgo"],
                filas_multas,
                [1.3, 8.6, 4.4, 1.7],
                alineaciones=["c", "l", "l", "c"],
                tam=7.5,
            )
        ilegales = multas.get("clausulas_ilegales") or []
        if ilegales:
            self._parrafo(doc, "Cláusulas que infringen la normativa vigente", 9.5,
                          negrita=True, espacio_despues=3)
            for clausula in ilegales[:8]:
                self._parrafo(doc, f"•  {clausula}", 9, espacio_despues=2)
        preguntas = multas.get("preguntas_foro") or []
        if preguntas:
            self._parrafo(doc, "Preguntas sugeridas para el foro de consultas", 9.5,
                          negrita=True, espacio_despues=3)
            for numero_pregunta, pregunta in enumerate(preguntas[:8], 1):
                self._parrafo(doc, f"{numero_pregunta}.  {pregunta}", 9, espacio_despues=2)

        # --- 8. Conclusión
        self._titulo_seccion(doc, 9, "Conclusión y recomendación")
        self._parrafo(
            doc,
            f"El procedimiento se considera {'admisible' if str(informes.get('estado_admisibilidad', '')).upper().startswith('APTO') else 'sujeto a verificación'} "
            f"para {self.perfil['razon_social']}. Se recomienda presentar la oferta del escenario equilibrado "
            f"({self._clp(eq.get('oferta_total_bruta_clp', 0))} con IVA incluido), dentro del plazo de cierre "
            f"informado ({expediente.get('fecha_cierre', 'ver ficha')}).",
            10,
        )

        self._pie_documento(doc, f"LICITAIA · {self.perfil['razon_social']} · Dossier {codigo} · Documento interno")
        doc.save(ruta_doc1)

    # ==================================================================
    # DOC 2 · COTIZACIÓN OFICIAL (1 hoja)
    # ==================================================================
    def generar_doc2_cotizacion_1_hoja(self, expediente, informes, escenarios, ruta_doc2):
        doc = Document()
        self._config_documento(doc, 1.5, 10)

        codigo = expediente.get("codigo", "")
        organismo = expediente.get("organismo", "Organismo público")
        presupuesto = int(expediente.get("presupuesto_estatal_clp") or 0)
        eq = escenarios.get("equilibrado", {})

        self._encabezado_empresa(
            doc,
            "Cotización",
            [
                f"N° de proceso: {codigo}",
                datetime.datetime.now().strftime("%d de %B de %Y").replace("November", "noviembre").replace("December", "diciembre").replace("January", "enero").replace("February", "febrero").replace("March", "marzo").replace("April", "abril").replace("May", "mayo").replace("June", "junio").replace("July", "julio").replace("August", "agosto").replace("September", "septiembre").replace("October", "octubre"),
                "Validez de la oferta: 60 días",
            ],
        )

        # --- Destinatario
        p_dest = doc.add_paragraph()
        p_dest.paragraph_format.space_after = Pt(1)
        r_dest = p_dest.add_run("SEÑORES")
        r_dest.font.size = Pt(7.5)
        r_dest.bold = True
        r_dest.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

        p_org = doc.add_paragraph()
        p_org.paragraph_format.space_after = Pt(0)
        r_org = p_org.add_run(str(organismo))
        r_org.bold = True
        r_org.font.size = Pt(11.5)
        r_org.font.color.rgb = RGBColor.from_string(self.AZUL)

        p_dir = doc.add_paragraph()
        p_dir.paragraph_format.space_after = Pt(10)
        r_dir = p_dir.add_run(
            f"Unidad de compra: {expediente.get('unidad_compradora', 'No informada')}   ·   "
            f"RUT: {expediente.get('rut_comprador', 'No informado')}   ·   "
            f"{expediente.get('comuna', '')} {expediente.get('region', '')}".strip()
        )
        r_dir.font.size = Pt(8)
        r_dir.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

        self._parrafo(
            doc,
            f"De nuestra consideración: por la presente presentamos nuestra oferta económica para el proceso "
            f"«{expediente.get('nombre', '')}», en estricta conformidad con las bases administrativas y técnicas "
            f"publicadas en Mercado Público, cuyo plazo de cierre es el {expediente.get('fecha_cierre', 'indicado en la ficha')}.",
            9.5,
            espacio_despues=8,
        )

        # --- 1. Objeto
        self._titulo_seccion(doc, 1, "Objeto de la oferta")
        alcance = informes.get("alcance_resumido_doc2") or []
        if alcance:
            for hito in alcance[:4]:
                self._parrafo(doc, f"•  {hito}", 9, espacio_despues=1)
        else:
            self._parrafo(doc, str(expediente.get("descripcion", ""))[:400], 9)

        # --- 2. Desglose económico
        self._titulo_seccion(doc, 2, "Desglose económico")
        neto = int(eq.get("oferta_neta_clp") or 0)
        iva = int(eq.get("iva_19_clp") or 0)
        bruto = int(eq.get("oferta_total_bruta_clp") or 0)
        self._tabla(
            doc,
            ["Ítem", "Descripción", "Cant.", "Valor unitario neto", "Total neto"],
            [["1", f"Servicio integral para el proceso {codigo}: {str(expediente.get('nombre', ''))[:90]}",
              "1", self._clp(neto), self._clp(neto)]],
            [1.2, 8.6, 1.4, 3.0, 2.8],
            alineaciones=["c", "l", "c", "r", "r"],
            tam=8.5,
        )

        tabla_tot = doc.add_table(rows=4, cols=2)
        tabla_tot.autofit = False
        tabla_tot.alignment = WD_TABLE_ALIGNMENT.RIGHT
        self._bordes_tabla(tabla_tot, interior=False)
        filas_totales = [
            ("Subtotal neto", self._clp(neto), False),
            ("IVA 19% (D.L. 825)", self._clp(iva), False),
            ("Total con IVA incluido", self._clp(bruto), True),
            (("Presupuesto oficial" if "Oficial" in str(expediente.get("origen_presupuesto", ""))
              else "Presupuesto referencial"), self._clp(presupuesto), False),
        ]
        for i, (etiqueta, valor, destacado) in enumerate(filas_totales):
            c_eti = tabla_tot.rows[i].cells[0]
            c_val = tabla_tot.rows[i].cells[1]
            c_eti.width = Cm(6.0)
            c_val.width = Cm(4.4)
            self._margen_celda(c_eti, 40, 40, 120, 100)
            self._margen_celda(c_val, 40, 40, 100, 120)
            if destacado:
                self._sombra_celda(c_eti, self.GRIS_FONDO)
                self._sombra_celda(c_val, self.GRIS_FONDO)
            p1 = c_eti.paragraphs[0]
            p1.alignment = WD_ALIGN_PARAGRAPH.RIGHT
            p1.paragraph_format.space_after = Pt(0)
            r1 = p1.add_run(etiqueta)
            r1.font.size = Pt(9 if destacado else 8.5)
            r1.bold = destacado
            r1.font.color.rgb = RGBColor.from_string(self.AZUL if destacado else self.GRIS_TEXTO)
            p2 = c_val.paragraphs[0]
            p2.alignment = WD_ALIGN_PARAGRAPH.RIGHT
            p2.paragraph_format.space_after = Pt(0)
            r2 = p2.add_run(valor)
            r2.font.size = Pt(10.5 if destacado else 8.5)
            r2.bold = destacado
            r2.font.color.rgb = RGBColor.from_string(self.AZUL if destacado else self.GRIS_TEXTO)
        doc.add_paragraph().paragraph_format.space_after = Pt(0)

        # --- 3. Condiciones
        self._titulo_seccion(doc, 3, "Condiciones comerciales")
        condiciones = [
            f"Plazo de entrega: {informes.get('plazo_entrega_dias_habiles', 15)} días hábiles desde la orden de compra.",
            "Forma de pago: 30 días contra recepción conforme y factura electrónica (Ley 21.131).",
            "Garantía técnica: 12 meses desde la recepción, con soporte preferente y respuesta en menos de 4 horas hábiles.",
            "La presente oferta no supera el presupuesto máximo informado por el organismo requirente.",
        ]
        for linea in condiciones:
            self._parrafo(doc, f"•  {linea}", 8.5, espacio_despues=1)

        # --- 4. Datos de pago
        self._titulo_seccion(doc, 4, "Datos del proveedor y de pago")
        self._tabla(
            doc,
            ["Razón social", "RUT", "Banco", "Cuenta", "Correo de contacto"],
            [[self.perfil["razon_social"], self.perfil["rut"], "Banco Mercado Pago",
              "Cuenta Vista", self.perfil["email_corporativo"]]],
            [3.6, 2.4, 3.0, 2.4, 4.0],
            alineaciones=["l", "c", "l", "l", "l"],
            tam=8,
        )

        # --- Firma
        p_firma = doc.add_paragraph()
        p_firma.paragraph_format.space_before = Pt(22)
        p_firma.paragraph_format.space_after = Pt(0)
        r_firma = p_firma.add_run("______________________________________")
        r_firma.font.size = Pt(9)
        r_firma.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

        p_nom = doc.add_paragraph()
        p_nom.paragraph_format.space_before = Pt(4)
        p_nom.paragraph_format.space_after = Pt(0)
        r_nom = p_nom.add_run(self.perfil["representante_legal"])
        r_nom.bold = True
        r_nom.font.size = Pt(9.5)
        r_nom.font.color.rgb = RGBColor.from_string(self.AZUL)

        p_cargo = doc.add_paragraph()
        p_cargo.paragraph_format.space_after = Pt(0)
        r_cargo = p_cargo.add_run(
            f"{self.perfil['cargo_representante']} · {self.perfil['razon_social']} · RUT {self.perfil['rut']}"
        )
        r_cargo.font.size = Pt(8)
        r_cargo.font.color.rgb = RGBColor.from_string(self.GRIS_SUAVE)

        self._pie_documento(
            doc,
            f"Documento generado por LICITAIA para {organismo[:60]} · Proceso {codigo}",
        )
        doc.save(ruta_doc2)

    # GENERADOR DOC 3: REPORTE FINANCIERO DE 4 PESTAÑAS EN WORD (ESTILIZADO)
    # --------------------------------------------------------------------------
    def generar_doc3_financiero_word(self, expediente, informes, escenarios, ruta_doc3):
        doc = Document()
        self._config_documento(doc, 1.6, 10.5)

        codigo = expediente.get("codigo", "")
        organismo = expediente.get("organismo", "Organismo público")
        nombre = str(expediente.get("nombre") or "Proceso")[:120]
        presupuesto = int(expediente.get("presupuesto_estatal_clp") or 0)
        eq = escenarios.get("equilibrado", {}) or {}
        ag = escenarios.get("agresivo", {}) or {}
        co = escenarios.get("conservador", {}) or {}

        def _clp(valor):
            try:
                return "$" + f"{int(valor):,}".replace(",", ".")
            except Exception:
                return "$0"

        self._encabezado_empresa(
            doc,
            "Informe financiero",
            [
                f"Proceso: {codigo}",
                f"Organismo: {organismo}",
                f"Presupuesto oficial: {_clp(presupuesto)} (IVA incluido)",
            ],
        )

        self._parrafo(doc, nombre, 9.5, negrita=True, espacio_despues=8)

        # 1. Escenarios
        self._titulo_seccion(doc, 1, "Escenarios de postulación")
        self._parrafo(
            doc,
            "El presupuesto publicado por el organismo corresponde al monto máximo con IVA "
            "incluido. Las ofertas se calculan hacia atrás desde ese tope, sin superarlo nunca.",
            9,
            espacio_despues=6,
        )
        filas = []
        for etiqueta, es in (("Competitivo", ag), ("Recomendado", eq), ("Conservador", co)):
            filas.append((
                etiqueta,
                f"{es.get('porcentaje_presupuesto', 0)}%",
                _clp(es.get("oferta_neta_clp", 0)),
                _clp(es.get("iva_19_clp", 0)),
                _clp(es.get("oferta_total_bruta_clp", 0)),
                _clp(es.get("costo_interno_total_clp", 0)),
                f"{es.get('margen_rentabilidad_pct', 0)}%",
            ))
        self._tabla(
            doc,
            ["Escenario", "% del tope", "Oferta neta", "IVA 19%", "Total bruto",
             "Costo interno", "Margen"],
            filas,
            [2.6, 1.5, 2.7, 2.2, 2.7, 2.7, 1.7],
            alineaciones=["l", "c", "r", "r", "r", "r", "c"],
            tam=8.5,
        )
        self._parrafo(
            doc,
            "El escenario recomendado maximiza la ganancia esperada. El conservador deja más "
            "margen por si aparecen costos no previstos durante la ejecución.",
            8.5,
            cursiva=True,
            espacio_despues=6,
        )

        # 2. Costos internos
        self._titulo_seccion(doc, 2, "Costos internos del proyecto")
        filas_c = [
            ("Horas de ingeniería, desarrollo y configuración",
             _clp(eq.get("costo_hh_clp", 0)),
             f"{informes.get('horas_ingenieria_estimadas', 40)} HH estimadas"),
            ("Infraestructura cloud y recursos de IA",
             _clp(eq.get("costo_cloud_clp", 0)),
             "Despliegue, licencias y operación"),
            ("Reserva técnica y gestión administrativa",
             _clp(eq.get("costo_imprevistos_clp", 0)),
             "Imprevistos operativos"),
            ("TOTAL COSTO INTERNO",
             _clp(eq.get("costo_interno_total_clp", 0)),
             "Se descuenta de la oferta neta"),
        ]
        self._tabla(
            doc,
            ["Centro de costo", "Monto", "Detalle"],
            filas_c,
            [8.0, 3.2, 6.4],
            alineaciones=["l", "r", "l"],
            tam=8.5,
            primera_columna_negrita=True,
        )

        # 3. Flujo de caja
        self._titulo_seccion(doc, 3, "Flujo de caja y liquidación de IVA")
        plazo = informes.get("plazo_entrega_dias_habiles", 15)
        lineas_caja = (
            f"Día 1 al {plazo}: inversión interna de {_clp(eq.get('costo_interno_total_clp', 0))}.",
            f"Día {plazo}: entrega conforme y emisión de factura por "
            f"{_clp(eq.get('oferta_total_bruta_clp', 0))}.",
            f"Día 20 del mes siguiente: pago de IVA (F29) por {_clp(eq.get('iva_19_clp', 0))}.",
            f"Pago a 30 días (Ley 21.131): ingreso líquido y ganancia de "
            f"{_clp(eq.get('ganancia_limpia_bolsillo_clp', 0))}.",
        )
        for linea in lineas_caja:
            self._parrafo(doc, f"•  {linea}", 9, espacio_despues=3)

        # 4. Dictamen
        self._titulo_seccion(doc, 4, "Dictamen de rentabilidad")
        self._tabla(
            doc,
            ["Indicador", "Valor"],
            [
                ("Margen neto sobre la oferta", f"{eq.get('margen_rentabilidad_pct', 0)}%"),
                ("Retorno sobre el costo (ROI)", f"{eq.get('roi_pct', 0)}%"),
                ("Ganancia de bolsillo", _clp(eq.get("ganancia_limpia_bolsillo_clp", 0))),
                ("Escenario recomendado", f"{eq.get('porcentaje_presupuesto', 0)}% del tope"),
            ],
            [10.6, 7.0],
            alineaciones=["l", "r"],
            tam=8.5,
            primera_columna_negrita=True,
        )
        self._parrafo(
            doc,
            f"El proyecto entrega un ROI de {eq.get('roi_pct', 0)}% y un margen neto de "
            f"{eq.get('margen_rentabilidad_pct', 0)}%. Se recomienda postular presentando el DOC 2.",
            9,
            negrita=True,
            espacio_despues=4,
        )

        doc.save(ruta_doc3)

    # --------------------------------------------------------------------------
    # GENERADOR EXCEL DE PROYECTO (.XLSX DE 4 PESTAÑAS ESTILO DASHBOARD)
    # --------------------------------------------------------------------------
    def _estilizar_excel(self, wb, expediente, escenarios):
        """Deja la planilla con aspecto de sistema (CRM/ERP): portada de KPIs,
        pestañas con color, paneles congelados y anchos legibles."""
        from openpyxl.utils import get_column_letter

        eq = escenarios.get("equilibrado", {})
        ag = escenarios.get("agresivo", {})
        co = escenarios.get("conservador", {})

        # --- Portada de resumen
        portada = wb.create_sheet(title="0_Resumen", index=0)
        portada.sheet_view.showGridLines = False
        portada.sheet_properties.tabColor = "1F2A44"

        portada.merge_cells("A1:F1")
        portada["A1"] = "LICITAIA · RESUMEN FINANCIERO"
        portada["A1"].fill = PatternFill("solid", start_color="1F2A44")
        portada["A1"].font = Font(name="Calibri", size=15, color="FFFFFF", bold=True)
        portada["A1"].alignment = Alignment(horizontal="center", vertical="center")
        portada.row_dimensions[1].height = 34

        portada.merge_cells("A2:F2")
        portada["A2"] = f"{expediente.get('codigo', '')} · {str(expediente.get('nombre', ''))[:70]}"
        portada["A2"].font = Font(name="Calibri", size=10, italic=True, color="475569")
        portada["A2"].alignment = Alignment(horizontal="center")
        portada.row_dimensions[2].height = 20

        kpis = [
            ("Presupuesto del organismo", expediente.get("presupuesto_estatal_clp", 0), "$#,##0"),
            ("Oferta recomendada (con IVA)", eq.get("oferta_total_bruta_clp", 0), "$#,##0"),
            ("Ganancia estimada", eq.get("ganancia_limpia_bolsillo_clp", 0), "$#,##0"),
            ("Margen sobre la venta", (eq.get("margen_rentabilidad_pct", 0) or 0) / 100.0, "0.0%"),
        ]
        fila = 4
        for etiqueta, valor, formato in kpis:
            portada.cell(row=fila, column=1, value=etiqueta).font = Font(
                name="Calibri", size=9, color="64748B", bold=True)
            celda = portada.cell(row=fila, column=1)
            celda.alignment = Alignment(vertical="center")
            portada.merge_cells(start_row=fila, start_column=1, end_row=fila, end_column=2)
            valor_celda = portada.cell(row=fila, column=3, value=valor)
            valor_celda.font = Font(name="Calibri", size=12, bold=True, color="0F172A")
            valor_celda.number_format = formato
            valor_celda.alignment = Alignment(horizontal="right", vertical="center")
            portada.row_dimensions[fila].height = 22
            fila += 1

        fila += 1
        portada.cell(row=fila, column=1, value="COMPARACIÓN DE ESCENARIOS").font = Font(
            name="Calibri", size=10, bold=True, color="1F2A44")
        fila += 1
        encabezados = ["Escenario", "% del tope", "Oferta con IVA", "Margen"]
        for columna, texto in enumerate(encabezados, start=1):
            celda = portada.cell(row=fila, column=columna, value=texto)
            celda.fill = PatternFill("solid", start_color="1E293B")
            celda.font = Font(name="Calibri", size=9, color="FFFFFF", bold=True)
            celda.alignment = Alignment(horizontal="center")
        fila += 1
        for etiqueta, datos in (("Competitivo", ag), ("Recomendado", eq), ("Conservador", co)):
            portada.cell(row=fila, column=1, value=etiqueta).font = Font(name="Calibri", size=9)
            portada.cell(row=fila, column=2, value=(datos.get("porcentaje_presupuesto", 0) or 0) / 100.0).number_format = "0%"
            portada.cell(row=fila, column=3, value=datos.get("oferta_total_bruta_clp", 0)).number_format = "$#,##0"
            portada.cell(row=fila, column=4, value=(datos.get("margen_rentabilidad_pct", 0) or 0) / 100.0).number_format = "0.0%"
            for columna in range(1, 5):
                portada.cell(row=fila, column=columna).border = Border(
                    bottom=Side(style="thin", color="E2E8F0"))
            if etiqueta == "Recomendado":
                for columna in range(1, 5):
                    portada.cell(row=fila, column=columna).fill = PatternFill(
                        "solid", start_color="ECFDF5")
                    portada.cell(row=fila, column=columna).font = Font(
                        name="Calibri", size=9, bold=True)
            fila += 1

        portada.column_dimensions["A"].width = 34
        portada.column_dimensions["B"].width = 14
        portada.column_dimensions["C"].width = 18
        portada.column_dimensions["D"].width = 12

        # --- Detalles del resto de las hojas
        colores = {"1_Escenarios_Oferta": "1F2A44", "2_Costos_Internos": "334155",
                   "3_Sensibilidad": "475569", "4_Conclusiones": "0F766E"}
        for hoja in wb.worksheets:
            if hoja.title == "0_Resumen":
                continue
            hoja.sheet_view.showGridLines = False
            hoja.sheet_properties.tabColor = colores.get(hoja.title, "64748B")
            hoja.freeze_panes = "A5"
            for indice, columna in enumerate(hoja.iter_cols(min_row=1, max_row=1), start=1):
                letra = get_column_letter(indice)
                hoja.column_dimensions[letra].width = 22 if indice == 1 else 16

        return wb

    def generar_excel_4_pestanas(self, expediente, informes, escenarios, ruta_excel):
        """Planilla financiera CON FÓRMULAS: el cliente cambia un dato y todo se recalcula."""
        wb = openpyxl.Workbook()
        wb.calculation.fullCalcOnLoad = True

        eq = escenarios.get("equilibrado", {}) or {}
        presupuesto = int(expediente.get("presupuesto_estatal_clp") or 0) or 1
        costo_total = int(eq.get("costo_interno_total_clp") or 0) or 1
        parametros = (informes or {}).get("parametros_precio") or {}
        margen_obj = float(parametros.get("margen_objetivo_pct") or 35) / 100.0
        peso_precio = float(parametros.get("peso_precio_pct") or 40) / 100.0
        pct_comp = float(parametros.get("pct_competencia") or 85) / 100.0

        azul = "1F2A44"
        slate = "1E293B"
        gris = "64748B"
        linea = "E2E8F0"
        verde = "ECFDF5"
        amarillo = "FEF9C3"

        def _titulo(hoja, celda, texto, ancho=8):
            hoja.merge_cells(start_row=hoja[celda].row, start_column=1,
                             end_row=hoja[celda].row, end_column=ancho)
            c = hoja[celda]
            c.value = texto
            c.fill = PatternFill("solid", start_color=azul)
            c.font = Font(name="Calibri", size=13, color="FFFFFF", bold=True)
            c.alignment = Alignment(horizontal="center", vertical="center")
            hoja.row_dimensions[c.row].height = 28

        def _entrada(hoja, fila, etiqueta, valor, formato):
            hoja.cell(row=fila, column=1, value=etiqueta).font = Font(
                name="Calibri", size=10, bold=True, color="334155")
            celda = hoja.cell(row=fila, column=2, value=valor)
            celda.fill = PatternFill("solid", start_color=amarillo)
            celda.font = Font(name="Calibri", size=10, bold=True, color="92400E")
            celda.number_format = formato
            celda.border = Border(*([Side(style="thin", color="F59E0B")] * 4))

        # ================================================================ 1) ESCENARIOS
        esc = wb.active
        esc.title = "1_Escenarios_Oferta"
        esc.sheet_view.showGridLines = False
        esc.sheet_properties.tabColor = azul
        _titulo(esc, "A1", f"SIMULACIÓN DE ESCENARIOS · {expediente.get('codigo', '')}")

        esc["A2"] = "Datos de entrada (celdas amarillas: cámbialas y todo se recalcula)"
        esc["A2"].font = Font(name="Calibri", size=9, italic=True, color=gris)

        _entrada(esc, 4, "Presupuesto oficial (tope con IVA)", presupuesto, "$#,##0")
        _entrada(esc, 5, "IVA", 0.19, "0%")
        _entrada(esc, 6, "Costo interno total", "='2_Costos_Internos'!$B$9", "$#,##0")
        _entrada(esc, 7, "Margen objetivo", margen_obj, "0.0%")

        encabezados = ["Escenario", "% del tope", "Oferta neta", "IVA 19%", "Total bruto",
                       "Costo interno", "Ganancia", "Margen", "ROI"]
        fila_encabezado = 9
        for columna, texto in enumerate(encabezados, start=1):
            c = esc.cell(row=fila_encabezado, column=columna, value=texto)
            c.fill = PatternFill("solid", start_color=slate)
            c.font = Font(name="Calibri", size=10, color="FFFFFF", bold=True)
            c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        esc.row_dimensions[fila_encabezado].height = 30

        escenarios_filas = [
            ("Competitivo", int((escenarios.get("agresivo") or {}).get("porcentaje_presupuesto") or 78)),
            ("Recomendado", int(eq.get("porcentaje_presupuesto") or 83)),
            ("Conservador", int((escenarios.get("conservador") or {}).get("porcentaje_presupuesto") or 85)),
        ]
        for indice, (nombre, porcentaje) in enumerate(escenarios_filas):
            fila = fila_encabezado + 1 + indice
            esc.cell(row=fila, column=1, value=nombre).font = Font(
                name="Calibri", size=10, bold=(nombre == "Recomendado"))
            porcentaje_celda = esc.cell(row=fila, column=2, value=porcentaje / 100.0)
            porcentaje_celda.number_format = "0%"
            porcentaje_celda.fill = PatternFill("solid", start_color=amarillo)
            porcentaje_celda.font = Font(name="Calibri", size=10, bold=True, color="92400E")
            esc.cell(row=fila, column=5, value=f"=$B$4*B{fila}").number_format = "$#,##0"
            esc.cell(row=fila, column=3, value=f"=E{fila}/(1+$B$5)").number_format = "$#,##0"
            esc.cell(row=fila, column=4, value=f"=E{fila}-C{fila}").number_format = "$#,##0"
            esc.cell(row=fila, column=6, value="=$B$6").number_format = "$#,##0"
            esc.cell(row=fila, column=7, value=f"=C{fila}-F{fila}").number_format = "$#,##0"
            esc.cell(row=fila, column=8, value=f"=IF(C{fila}=0,0,G{fila}/C{fila})").number_format = "0.0%"
            esc.cell(row=fila, column=9, value=f"=IF(F{fila}=0,0,G{fila}/F{fila})").number_format = "0.0%"
            for columna in range(1, 10):
                celda = esc.cell(row=fila, column=columna)
                celda.border = Border(bottom=Side(style="thin", color=linea))
                if nombre == "Recomendado":
                    celda.fill = PatternFill("solid", start_color=verde)
                    celda.font = Font(name="Calibri", size=10, bold=True)
            esc.row_dimensions[fila].height = 20

        esc["A14"] = "Alerta de margen:"
        esc["A14"].font = Font(name="Calibri", size=9, bold=True, color=gris)
        esc["B14"] = '=IF(H11<$B$7,"El escenario recomendado NO alcanza el margen objetivo","Cumple el margen objetivo")'
        esc["B14"].font = Font(name="Calibri", size=9, bold=True, color="B45309")
        esc.merge_cells("B14:F14")
        # --- Explicación del cálculo EN LA MISMA HOJA (pedido del cliente)
        esc["A16"] = "CÓMO SE CALCULA CADA CIFRA DE ESTA HOJA"
        esc["A16"].font = Font(name="Calibri", size=10, bold=True, color=azul)
        explicacion_hoja = [
            ("Total bruto", "→ presupuesto (B4) × el % del tope de esa fila. Es lo que el Estado pagaría, IVA incluido."),
            ("Oferta neta", "→ total bruto ÷ (1 + IVA de B5). Es tu ingreso antes de IVA."),
            ("Ganancia", "→ oferta neta − costo interno (B6). Es la plata que efectivamente te queda."),
            ("Ganancia al bolsillo", "Es la misma ganancia: ya está sin IVA y con todos los costos descontados."),
            ("Margen neto", "→ ganancia ÷ oferta neta. Si dice 11%, de cada $100 facturados te quedan $11."),
            ("ROI", "→ ganancia ÷ costo interno. Si dice 30%, por cada $100 invertidos ganas $30."),
            ("% del tope", "Puedes cambiarlo en las celdas amarillas: todo lo demás se recalcula solo."),
        ]
        fila_expl = 17
        for concepto, detalle in explicacion_hoja:
            esc.cell(row=fila_expl, column=1, value=concepto).font = Font(
                name="Calibri", size=9, bold=True, color="334155")
            celda_det = esc.cell(row=fila_expl, column=2, value=detalle)
            celda_det.font = Font(name="Calibri", size=9, color=gris)
            celda_det.alignment = Alignment(wrap_text=True, vertical="center")
            esc.merge_cells(start_row=fila_expl, start_column=2,
                            end_row=fila_expl, end_column=9)
            esc.row_dimensions[fila_expl].height = 26
            fila_expl += 1

        esc.column_dimensions["A"].width = 38
        for letra in ("B", "C", "D", "E", "F", "G", "H", "I"):
            esc.column_dimensions[letra].width = 15
        esc.freeze_panes = "A10"

        # ================================================================ 2) COSTOS
        costos = wb.create_sheet(title="2_Costos_Internos")
        costos.sheet_view.showGridLines = False
        costos.sheet_properties.tabColor = "334155"
        _titulo(costos, "A1", "DESGLOSE DE COSTOS INTERNOS")
        costos["A2"] = "Edita las cantidades y valores: el total alimenta toda la planilla."
        costos["A2"].font = Font(name="Calibri", size=9, italic=True, color=gris)

