    def _entregar_por_portal(self, carpeta_proyecto, expediente, informes, escenarios):
        """Guarda el manifiesto, avisa por correo con el link y devuelve el enlace.

        La entrega es exitosa cuando los documentos están en el disco y existe el
        link: si el correo falla, NO se marca el proyecto como pendiente.
        """
        codigo = expediente["codigo"]
        self._guardar_manifest(carpeta_proyecto, expediente, escenarios)
        enlace = self._link_portal(codigo)
        archivos = self._recopilar_archivos_proyecto(carpeta_proyecto)
        print(f"   📁 [PORTAL] {len(archivos)} archivo(s) guardados en disco")
        print(f"   🔗 [PORTAL] Enlace privado: {enlace}")

        html = self._html_correo_portal(expediente, informes, escenarios, enlace)
        enviado = False
        if URL_APPS_SCRIPT and _notificaciones_activas():
            payload = {
                "empresa": "Mantytech_SpA",
                "email_destino": self.perfil["email_notificaciones"],
                "asunto_email": f"✅ [LICITAIA] {codigo} listo para revisar",
                "html_resumen": html,
                "enviar_correo": True,
                "id_envio": f"{codigo}-{datetime.datetime.now().strftime('%Y%m%d%H%M')}",
                "subcarpeta_portal": "",
                "codigo_id": codigo,
                "archivos": [],
            }
            ok, _carpeta, detalle = self._enviar_lote_apps_script(payload, timeout=90)
            enviado = ok
            if ok:
                print(f"   ✅ Correo enviado a {self.perfil['email_notificaciones']} con el enlace")
            else:
                print(f"   [!] El correo no salió ({detalle}). El enlace sigue disponible.")
        if not enviado:
            try:
                with open(os.path.join(carpeta_proyecto, "CORREO_PENDIENTE.html"), "w",
                          encoding="utf-8") as f:
                    f.write(html + f"\n<!-- enlace: {enlace} -->")
            except Exception:
                pass

        return {"subido_drive": True, "url_carpeta_drive": enlace, "modo": "portal"}

    # ------------------------------------------------------------------
    # PUENTE GOOGLE DRIVE v5.4 (honesto, por lotes y con reintentos reales)
    # ------------------------------------------------------------------
    def _recopilar_archivos_proyecto(self, carpeta_proyecto):
        """Archivos a subir. El CRM Maestro NUNCA entra aquí (iba duplicado en
        cada carpeta y engordaba el envío hasta tumbar Apps Script)."""
        archivos = []
        for raiz, _, files in os.walk(carpeta_proyecto):
            for nombre in files:
                if nombre.startswith("~$") or nombre.startswith("."):
                    continue
                ruta = os.path.join(raiz, nombre)
                try:
                    tam = os.path.getsize(ruta)
                except OSError:
                    continue
                if tam < 200:
                    continue
                archivos.append((ruta, tam))

        def _prioridad(item):
            base = os.path.basename(item[0]).upper()
            for i, prefijo in enumerate(("DOC1", "DOC2", "DOC3", "PLANILLA", "ANEXO_CLON")):
                if base.startswith(prefijo):
                    return i
            return 5

        archivos.sort(key=_prioridad)
        return archivos

    @staticmethod
    def _a_base64(ruta):
        with open(ruta, "rb") as f:
            return base64.b64encode(f.read()).decode("utf-8")

    def _enviar_lote_apps_script(self, payload, timeout=240):
        """(ok, folder_url, detalle). OK solo si status=='ok' Y hay carpeta.

        Antes bastaba HTTP 200: Apps Script devuelve 200 incluso cuando falla por
        cuota, y por eso se perdían carpetas con un falso 'status': 'ok'.
        """
        ultimo = "sin intentos"
        for intento in range(1, REINTENTOS_DRIVE + 1):
            # Si el primer intento pudo haber llegado igual (timeout, respuesta
            # rara), el reintento va SIN datos de correo: así no se duplica el email.
            cuerpo_payload = payload
            if intento > 1 and isinstance(payload, dict):
                cuerpo_payload = dict(payload)
                cuerpo_payload["html_resumen"] = ""
                cuerpo_payload["asunto_email"] = ""
                cuerpo_payload["enviar_correo"] = False
                print("      (reintento sin correo, para no duplicarlo)")
            try:
                resp = requests.post(
                    URL_APPS_SCRIPT,
                    data=json.dumps(cuerpo_payload, ensure_ascii=False),
                    headers={"Content-Type": "text/plain;charset=utf-8"},
                    timeout=timeout,
                    allow_redirects=True,
                )
                cuerpo = resp.text or ""
                if resp.status_code != 200:
                    pista = ""
                    if "accounts.google.com" in cuerpo or "iniciar sesión" in cuerpo.lower():
                        pista = " (el despliegue de Apps Script NO es público: 'Cualquier persona')"
                    elif "Service unavailable" in cuerpo or "quota" in cuerpo.lower():
                        pista = " (cuota de Google agotada)"
                    ultimo = f"HTTP {resp.status_code}{pista}"
                else:
                    js = None
                    try:
                        js = resp.json()
                    except Exception:
                        ultimo = ("HTTP 200 pero la respuesta NO es JSON "
                                  "(cuota excedida o excepción interna de Apps Script)")
                    if js is not None:
                        estado = str(js.get("status", "")).strip().lower()
                        carpeta = js.get("folder_url") or js.get("carpeta_url") or js.get("url") or ""
                        if estado == "ok" and carpeta:
                            return True, carpeta, ""
                        detalle = str(js.get("mensaje") or js.get("error") or js.get("detalle") or "")[:160]
                        ultimo = (f"status={estado or 'vacío'} | carpeta={'sí' if carpeta else 'no'}"
                                  + (f" | {detalle}" if detalle else ""))
            except Exception as e:
                ultimo = f"excepción: {e}"
            print(f"      [!] Drive intento {intento}/{REINTENTOS_DRIVE}: {ultimo}")
            if intento < REINTENTOS_DRIVE:
                time.sleep(6 * intento)
        return False, "", ultimo

