    """Manda un WhatsApp de prueba.  Uso: --probar-whatsapp +56912345678"""
    destino = (destino or "").strip() or (WHATSAPP_CLIENTE[0] if WHATSAPP_CLIENTE else WHATSAPP_DESTINO)
    print("")
