    print(f"   API       : {WHATSAPP_API_URL or '(sin configurar)'}")
    print(f"   Instancia : {WHATSAPP_INSTANCIA or '(sin configurar)'}")
    print(f"   API key   : {'sí' if WHATSAPP_APIKEY else 'NO'}")
